window.DIGEST_ARCHIVE=window.DIGEST_ARCHIVE||{};window.DIGEST_ARCHIVE["2026-08-03"]={"date":"2026-08-03","dateKR":"2026년 8월 3일","dateEN":"August 3, 2026","total":94,"sections":[{"code":"TOP","kTitle":"주요뉴스","eTitle":"Top News","items":[{"code":"TOP","title":"CMA CGM and Stonepeak close $2.4bn 'United Ports' terminal joint venture","titleKR":"CMA CGM·스톤피크(Stonepeak), 24억 달러 규모 'United Ports' 터미널 합작사 출범","src":"The Maritime Executive","date":"2026-07-28","kSum":"CMA CGM과 인프라 투자사 스톤피크(Stonepeak)가 'United Ports' 합작법인 설립을 완료했다. 스톤피크가 24억 달러를 투자해 25% 지분을, CMA CGM이 75%와 운영권을 갖는다. 미국·브라질·스페인·대만·베트남의 9개 컨테이너 터미널이 초기 포트폴리오다.","eSum":"CMA CGM and infrastructure investor Stonepeak completed a joint venture called United Ports. Stonepeak invests $2.4bn for a 25% stake while CMA CGM keeps 75% and full control. The initial portfolio spans nine terminals across the US, Brazil, Spain, Taiwan and Vietnam.","kImp":"세계 3대 컨테이너 선사가 외부 인프라 자본을 끌어들여 터미널 확장 경쟁을 가속하는 신호다.","eImp":"A top-three box carrier tapping external capital accelerates the liners' race to expand terminal networks.","url":"https://maritime-executive.com/article/cma-cgm-plans-growth-in-port-terminals-with-2-4b-investment-from-stonepeak"},{"code":"TOP","title":"Scorpio Tankers takes stake in eight-VLCC newbuild venture and adds LR2 pair","titleKR":"스코르피오 탱커스(Scorpio Tankers), VLCC 8척 신조 벤처 지분 확보하고 LR2 2척 추가","src":"Splash247","date":"2026-07-31","kSum":"미국 상장 제품선사 스코르피오 탱커스(Scorpio Tankers)가 VLCC 8척 신조 벤처에 소수 지분으로 참여하고 LR2 제품선 2척을 추가 발주했다. 원유 부문으로의 확장 움직임으로 해석된다.","eSum":"US-listed product tanker owner Scorpio Tankers took a minority stake in an eight-ship VLCC newbuilding venture and separately ordered two more LR2 product tankers, signalling expansion into crude.","kImp":"탱커 시황 강세 속 주요 선사가 대형 원유선까지 손을 뻗으며 신조 발주 열기가 이어진다.","eImp":"A leading tanker owner reaching into large crude carriers underlines the sustained newbuilding boom.","url":"https://splash247.com/scorpio-tankers-takes-stake-in-eight-vlcc-newbuilds-and-adds-lr2-pair/"},{"code":"TOP","title":"Seanergy commits nearly $600m to capesize fleet renewal","titleKR":"시너지 마리타임(Seanergy), 케이프사이즈 선대 갱신에 약 6억 달러 투입","src":"Splash247","date":"2026-07-31","kSum":"그리스 벌크선사 시너지 마리타임(Seanergy Maritime)이 일본 건조 케이프사이즈 2척에 약 1억3천만 달러를 지출한다. 이로써 총 8척, 5억9,100만 달러 규모의 선대 갱신 프로그램이 완성된다.","eSum":"US-listed Greek bulker owner Seanergy Maritime agreed to spend about $130m on two Japanese-built capesizes, lifting its fleet-renewal programme to eight ships worth $591m.","kImp":"케이프사이즈 노후선 교체 흐름이 이어지며 드라이벌크 선사의 자본 지출이 확대되고 있다.","eImp":"Continued capesize fleet renewal shows dry bulk owners ramping capital spending.","url":"https://splash247.com/seanergy-stacks-up-nearly-600m-in-fleet-investment/"},{"code":"TOP","title":"NYK invests in MidOcean Energy to expand LNG footprint","titleKR":"일본우선(NYK), 미드오션에너지(MidOcean Energy) 투자로 LNG 사업 확장","src":"Splash247","date":"2026-07-31","kSum":"일본 해운 대기업 일본우선(NYK)이 영국 LNG 기업 미드오션에너지(MidOcean Energy)에 투자했다. 상류 LNG 자산으로 사업 영역을 넓히려는 전략이다.","eSum":"Japanese shipping major Nippon Yusen Kaisha (NYK) invested in UK-based LNG company MidOcean Energy, broadening its position into upstream LNG assets.","kImp":"대형 선사가 단순 수송을 넘어 LNG 밸류체인 전반으로 통합을 확대하는 흐름이다.","eImp":"A major carrier moving deeper into the LNG value chain signals owners integrating beyond pure transport.","url":"https://splash247.com/nyk-invests-in-midocean-energy-to-expand-lng-footprint/"},{"code":"TOP","title":"BP moves to offload its North Sea business","titleKR":"BP, 북해(North Sea) 사업 매각 추진","src":"Splash247","date":"2026-07-31","kSum":"에너지 메이저 BP가 북해(North Sea) 사업부 매각에 나섰다. 성숙 유전 자산 정리 움직임으로 해당 해역 오프쇼어 물류·서비스 시장에도 영향이 예상된다.","eSum":"Energy major BP is moving to sell its North Sea business, and divesting the mature basin's assets is likely to ripple through the region's offshore logistics and services market.","kImp":"북해 자산 재편은 해당 해역 오프쇼어 지원선·서비스 수요에 직접 변화를 가져올 수 있다.","eImp":"A BP North Sea exit could reshape demand for offshore support vessels and services.","url":"https://splash247.com/bp-moves-to-offload-north-sea-business/"},{"code":"TOP","title":"Singapore hands out eight new LNG bunkering licences","titleKR":"싱가포르(Singapore), LNG 벙커링 신규 라이선스 8건 발급","src":"The Maritime Executive","date":"2026-07-31","kSum":"싱가포르 해사항만청(MPA)이 9월 1일부터 유효한 5년짜리 LNG 벙커링 라이선스 8건을 발급했다. 아람코 트레이딩, 엑슨모빌, 셸, 페트로차이나 등이 포함돼 세계 최대 급유항의 LNG 공급망이 확대된다.","eSum":"The Maritime and Port Authority of Singapore awarded eight five-year LNG bunker supplier licences effective 1 September, including Aramco Trading, ExxonMobil, Shell and PetroChina.","kImp":"세계 최대 급유항이 LNG 공급자를 대폭 늘리며 대체연료 벙커링 인프라 경쟁이 본격화한다.","eImp":"The largest bunkering hub broadening its LNG supplier base intensifies alternative-fuel bunkering competition.","url":"https://maritime-executive.com/article/singapore-issues-eight-new-lng-bunkering-licenses"},{"code":"TOP","title":"Royal Caribbean posts strong Q2 despite fuel costs and geopolitical impact","titleKR":"로열캐리비안(Royal Caribbean), 연료비·지정학 리스크에도 2분기 호실적","src":"The Maritime Executive","date":"2026-07-28","kSum":"로열캐리비안 그룹(Royal Caribbean Group)이 시장 예상을 웃도는 2분기 실적을 냈다. 연료비 상승과 지정학적 예약 영향에도 비용을 통제하며 총매출 6% 증가를 기록했다.","eSum":"Royal Caribbean Group reported second-quarter results that beat estimates, controlling costs despite higher fuel prices and a modest booking impact from geopolitics. Total revenue rose 6%.","kImp":"크루즈 대장주의 견조한 실적은 지정학 불안 속에서도 여행 수요가 탄탄함을 시사한다.","eImp":"Strong results from the cruise bellwether signal resilient leisure-travel demand.","url":"https://maritime-executive.com/article/royal-caribbean-posts-strong-q2-despite-fuel-costs-geopolitical-impact"},{"code":"TOP","title":"Maersk Tankers and HD Hyundai Samho celebrate first large ammonia carrier","titleKR":"머스크 탱커스(Maersk Tankers)·HD현대삼호, 첫 대형 암모니아 운반선 인도","src":"The Maritime Executive","date":"2026-07-28","kSum":"머스크 탱커스(Maersk Tankers)와 HD현대삼호가 첫 대형 암모니아 운반선 인도를 기념했다. 'Jane Maersk'는 2023년 11월 발주한 5척 시리즈 중 첫 호선이다.","eSum":"Maersk Tankers and HD Hyundai Samho marked delivery of their first large ammonia carrier. Named Jane Maersk, it is the first of a five-vessel order placed in November 2023.","kImp":"암모니아 운반선 인도는 무탄소 연료 공급망 구축을 향한 실질적 진전을 보여준다.","eImp":"The delivery marks tangible progress toward the zero-carbon fuel supply chain.","url":"https://maritime-executive.com/article/maersk-tankers-and-hd-hyundai-samho-celebrate-first-large-ammonia-carrier"},{"code":"TOP","title":"HD Hyundai launches first ship from revitalized Philippine (Subic) shipyard","titleKR":"HD현대, 재가동한 필리핀 수비크(Subic) 조선소서 첫 선박 진수","src":"The Maritime Executive","date":"2026-07-29","kSum":"HD현대가 옛 한진 수비크(Subic) 조선소를 인수·재가동한 뒤 첫 신조선을 진수했다. 11만5천 dwt 석유화학 제품운반선 'Orion Jade'가 2019년 가동 중단됐던 야드의 첫 선박이다.","eSum":"HD Hyundai launched its first newbuild at the former Hanjin Subic Bay shipyard in the Philippines. The 115,000 dwt petrochemical tanker Orion Jade is the first ship built at the yard, idle since 2019.","kImp":"한국 조선사의 필리핀 야드 재가동은 글로벌 건조능력 확충과 지역 조선업 부활의 상징이다.","eImp":"A Korean builder reviving a Philippine yard signals expanding global shipbuilding capacity.","url":"https://maritime-executive.com/article/hd-hyundai-launches-first-ship-from-revitalized-philippine-shipyard"}]},{"code":"ACC","kTitle":"사고","eTitle":"Accidents","items":[{"code":"ACC","type":"accident","title":"Explosion and fire on Norwegian chemical tanker Bergstraum carrying sulfuric acid","titleKR":"황산 적재 노르웨이 화학운반선 'Bergstraum' 폭발·화재","src":"SAFETY4SEA","date":"2026-07-28","kSum":"우트킬렌(Utkilen) 운영 화학운반선 'Bergstraum'이 노르웨이 흐발레르 앞바다 정박 중 폭발·화재가 났다. 빈 탱크 내부에서 발생했으며 승선 15명은 무사하고 황산 유출은 없었다.","eSum":"The Utkilen-operated chemical tanker Bergstraum suffered an explosion and fire while anchored off Hvaler, Norway. The blast occurred inside an empty tank; all 15 crew were unharmed and no sulfuric acid was released.","kCause":"예비 정보에 따르면 용접 작업 중 빈 탱크 내부에서 폭발이 발생한 것으로 추정된다.","eCause":"Preliminary information indicates the explosion occurred inside an empty tank during welding work.","kLes":"탱커의 '빈' 탱크도 잔류 가스로 폭발 위험이 크므로 열간작업 전 가스 프리·엄격한 허가 절차가 필수다.","eLes":"'Empty' tanker tanks can hold explosive vapours, so gas-freeing and strict hot-work permit control are essential before welding.","url":"https://safety4sea.com/fire-contained-onboard-chemical-tanker-carrying-sulfuric-acid-off-norway/"},{"code":"ACC","type":"accident","title":"Bulker Pilatus Marie grounds in the Dardanelles after engine failure","titleKR":"벌크선 'Pilatus Marie', 엔진 고장으로 다르다넬스(Dardanelles) 해협서 좌초","src":"The Maritime Executive","date":"2026-07-30","kSum":"러시아로 향하던 산마리노 국적 벌크선 'Pilatus Marie'(56,632 dwt)가 다르다넬스(Dardanelles) 해협 나라 굴곡부 접근 중 엔진 고장으로 좌초, 통항이 밤새 중단됐다. 예인선 투입으로 약 12시간 만에 이초됐다.","eSum":"The San Marino-flagged bulker Pilatus Marie (56,632 dwt) grounded approaching the Nara turn in the Dardanelles after an engine failure, halting strait traffic overnight. Tugs freed the vessel after about 12 hours.","kCause":"주기관 고장에 따른 조종 불능으로 협수로에서 좌초. 이 선박은 앞서 PSC에서 기관 결함 지적 이력이 있다.","eCause":"Loss of propulsion from main-engine failure led to grounding; the ship had prior PSC deficiencies for engines.","kLes":"협수로 통항 전 기관 상태 점검·예방정비와 반복되는 PSC 지적의 근본 원인 해소가 핵심이다.","eLes":"Engine checks, preventive maintenance and closing out recurring PSC findings are critical before confined-water transits.","url":"https://maritime-executive.com/article/turkish-bulker-heading-to-russia-breaks-down-and-blocks-the-dardanelles"},{"code":"ACC","type":"accident","title":"Viking river cruise ship Viking Ullur grounds and is evacuated on the Danube","titleKR":"바이킹 리버크루즈선 'Viking Ullur', 다뉴브강(Danube)서 좌초·승객 대피","src":"The Maritime Executive","date":"2026-07-28","kSum":"바이킹(Viking) 리버크루즈선 'Viking Ullur'가 7월 28일 새벽 다뉴브강(Danube)서 좌초해 불가리아 국경경찰 주도로 승객이 대피했다. 당국은 낮은 수위와 야간 항해를 원인으로 지목했다.","eSum":"The Viking river cruise ship Viking Ullur grounded on the Danube early on 28 July, prompting an evacuation led by Bulgaria's Border Police. Authorities cited low water levels and darkness.","kCause":"극심한 가뭄에 따른 저수위와 야간 항해 여건에서 항로 이탈로 좌초한 것으로 파악된다.","eCause":"Grounding after leaving the channel amid drought-driven low water and night navigation.","kLes":"이상 기후로 인한 내륙수로 저수위 시 흘수 여유·항로 유지 관리를 강화하고 야간 통항 위험을 재평가해야 한다.","eLes":"As low water hits inland waterways, operators must tighten under-keel clearance and reassess night transits.","url":"https://maritime-executive.com/article/viking-river-cruise-ship-evacuated-after-grounding-on-the-danube"},{"code":"ACC","type":"accident","title":"Saudi oil tanker Encelia hit by Houthi missile in the Red Sea, bow fire","titleKR":"사우디 유조선 'Encelia', 홍해(Red Sea)서 후티 미사일 피격·선수 화재","src":"Al Jazeera","date":"2026-07-28","kSum":"예멘 후티(Houthi)가 7월 20일 선포한 해상 봉쇄 이후 처음으로 사우디 유조선 'Encelia'가 홍해 통항 중 미사일 공격을 받았다. 선수부 화재가 났으나 전 승무원은 안전했다.","eSum":"The Saudi oil tanker Encelia was struck while transiting the Red Sea, the first attack since the Houthis declared a maritime blockade on 20 July. A fire broke out at the bow, but all crew were safe.","kCause":"후티의 대사우디 해상 봉쇄 선언에 따른 미사일 공격.","eCause":"A missile strike under the Houthis' declared maritime blockade against Saudi Arabia.","kLes":"홍해·바브엘만데브 통항선은 위협 재확산에 대비해 항로 회피·경계 강화·손상통제 대비를 철저히 해야 한다.","eLes":"Red Sea transiting ships must be ready with rerouting, vigilance and damage-control preparedness as threats resurge.","url":"https://www.aljazeera.com/news/2026/7/28/yemens-houthis-claim-missile-attack-on-saudi-arabia-oil-tanker"},{"code":"ACC","type":"accident","title":"Turkish-owned general cargo ship ATA 2 seriously damaged by drone fire in Black Sea","titleKR":"터키 소유 일반화물선 'ATA 2', 흑해(Black Sea)서 드론 공격에 큰 손상","src":"Splash247","date":"2026-07-31","kSum":"터키 소유 일반화물선 'ATA 2'(6,555 dwt)가 흑해에서 드론 공격을 받아 심각한 손상을 입었다. 상선·에너지 터미널을 겨냥한 공격이 분쟁 양측에서 심화되는 가운데 발생했다.","eSum":"The Turkish-owned general cargo ship ATA 2 (6,555 dwt) suffered serious damage from drone fire in the Black Sea, as attacks on merchant vessels and energy terminals intensify on both sides.","kCause":"흑해 분쟁 격화에 따른 상선 대상 드론 공격.","eCause":"A drone attack on merchant shipping amid the escalating Black Sea conflict.","kLes":"제3국 상선도 무차별 공격에 노출될 수 있어 흑해 항로 선사는 전쟁위험 평가·회피 항로를 지속 갱신해야 한다.","eLes":"Third-country merchant ships are exposed, so Black Sea operators must continually update war-risk assessments and routing.","url":"https://splash247.com/black-sea-ship-attacks-spread/"},{"code":"ACC","type":"accident","title":"Drone strike hits FSRU and LNG carrier at Egypt's Damietta terminal","titleKR":"이집트 다미에타(Damietta) 터미널서 FSRU·LNG선 드론 피격","src":"Splash247","date":"2026-07-30","kSum":"이집트 다미에타(Damietta) 항의 부유식 저장·재기화 설비(FSRU)와 LNG 운반선이 드론 공격을 받았다. 미국 소유 FSRU 'Energos'가 피해를 입었으며 이란이 유력 배후로 지목된다.","eSum":"A floating storage and regasification unit (FSRU) and an LNG carrier were hit by a drone strike at Egypt's Damietta port. The US-owned FSRU Energos was damaged, with Iran named the chief suspect.","kCause":"항만 정박 중 에너지 인프라를 겨냥한 드론 공격(배후 조사 중).","eCause":"A drone strike targeting energy infrastructure while berthed (attribution under investigation).","kLes":"가스 터미널·정박 선박 등 고정 자산에 대한 원격 공격 위험이 커져 항만 방호·비상대응 강화가 요구된다.","eLes":"Rising risk of remote strikes on fixed assets like gas terminals calls for stronger port protection and emergency response.","url":"https://splash247.com/drone-strike-hits-fsru-and-lng-carrier-at-egyptian-terminal/"},{"code":"ACC","type":"accident","title":"Port of Tyne to close river to clear containership and collapsed crane after allision","titleKR":"타인항(Port of Tyne), 충돌사고 후 컨테이너선·붕괴 크레인 정리 위해 강 폐쇄","src":"The Maritime Executive","date":"2026-07-30","kSum":"7월 19일 풍력터빈 설치선 'Wind Orca'(카델러 운영)가 출항 중 접안 컨테이너선 'BG Orange'와 충돌해 750t 갠트리 크레인이 붕괴, 선체 위로 넘어졌다. 손상 컨테이너에서 플라스틱 펠릿이 유출됐고 7월 30일 타인강 일부가 9시간 폐쇄됐다.","eSum":"On 19 July the wind-turbine installation vessel Wind Orca (Cadeler) collided with the berthed containership BG Orange while leaving the Port of Tyne, toppling a 750-tonne gantry crane onto the ship. Plastic pellets spilled and part of the River Tyne closed for nine hours on 30 July.","kCause":"설치선의 출항 조종 중 접안 선박과의 충돌(allision)로 크레인 붕괴·화물 손상 발생.","eCause":"An allision during the installation vessel's departure manoeuvre, causing crane collapse and cargo damage.","kLes":"대형 특수선의 부두 이·접안 조종 시 인접 선박·안벽 설비와의 안전거리 확보와 예인·통제 절차를 강화해야 한다.","eLes":"Manoeuvring large specialised vessels near berths demands tighter clearance and robust tug and control procedures.","url":"https://maritime-executive.com/article/port-and-river-tyne-to-close-to-clear-damaged-containership-and-crane"}],"type":"accident"},{"code":"PSC","kTitle":"항만국통제(PSC)","eTitle":"Port State Control","items":[{"code":"PSC","title":"China's Panama-flag detention campaign starts to ease after Beijing–Panama talks","titleKR":"중국의 파나마(Panama) 선적 억류 캠페인, 베이징-파나마 협상 후 진정 국면","src":"Splash247","date":"2026-07-31","kSum":"중국 항만의 파나마(Panama) 선적 억류가 급감했다. 파나마는 7월 억류가 16척으로 5월 140척에서 크게 줄었다고 밝혔다. 파나마 대법원의 CK허치슨 항만 계약 무효 판결 이후 급증했던 PSC 명분 억류가 협상으로 완화되고 있다.","eSum":"Detentions of Panama-flagged ships at Chinese ports fell sharply, with Panama reporting 16 in July, down from a peak of 140 in May. The PSC-framed campaign, which surged after Panama's court voided CK Hutchison's port concessions, is easing after Beijing–Panama talks.","kImp":"PSC가 지정학적 압박 수단으로 쓰인 이례적 사례로, 특정 선적 선주의 억류 위험이 완화되고 있다.","eImp":"A rare case of PSC used as geopolitical leverage is now easing, reducing detention risk for owners under that flag.","url":"https://splash247.com/chinas-panama-flag-detention-campaign-starts-to-ease/"},{"code":"PSC","title":"IMPA 2026 campaign records 13% pilot-transfer non-compliance","titleKR":"IMPA 2026 캠페인, 도선사 이·승선 설비 부적합 13% 기록","src":"The Maritime Executive","date":"2026-08-01","kSum":"국제도선사협회(IMPA)의 2026 안전 캠페인에서 34개국 4,051건 중 13%가 도선사 이·승선 설비 부적합으로 나타났으며, 파일럿 사다리 배치가 최다 지적 항목이었다. 노티컬인스티튜트는 학생 대상 도선 이송 안전 공모전을 시작했다.","eSum":"IMPA's 2026 Safety Campaign recorded a 13% non-compliance rate across 4,051 entries from 34 countries, with pilot ladder arrangements the leading finding. The Nautical Institute launched a student competition on pilot-transfer safety.","kImp":"도선사 이송 설비는 PSC·사망사고의 상습 지적 위험 요인으로, 지속적 부적합률은 승선 안전 개선이 시급함을 보여준다.","eImp":"Pilot transfer arrangements are a recurring PSC and fatality-risk area; the persistent non-compliance rate underscores an urgent need to improve boarding safety.","url":"https://maritime-executive.com/corporate/global-competition-launched-as-pilot-transfer-non-compliance-remains-at-13"}]},{"code":"PCTC","kTitle":"자동차운반선(PCTC)","eTitle":"Car Carriers (PCTC)","items":[{"code":"PCTC","title":"Sallaum Lines orders LNG dual-fuel, ammonia-ready 8,600 CEU PCTC","titleKR":"살라움 라인즈(Sallaum Lines), LNG 이중연료·암모니아 대응 8,600 CEU PCTC 발주","src":"MarineLink","date":"2026-07-28","kSum":"스위스 선사 살라움 라인즈(Sallaum Lines)가 중국 자오상 진링과 8,600 CEU급 순수 자동차·트럭 운반선(PCTC) 1+1척 건조계약을 체결했다. LNG 이중연료·암모니아 대응 설계로 2029년 인도 예정이며, 확정 신조는 9척으로 늘었다.","eSum":"Swiss operator Sallaum Lines signed a 1+1 order with China Merchants Jinling for 8,600 CEU pure car and truck carriers. The LNG dual-fuel, ammonia-ready vessels deliver in 2029, lifting its firm newbuild programme to nine ships.","kImp":"중견 선사도 LNG·암모니아 대응 대형 PCTC로 선대를 확장하며 차세대 친환경 자동차운반선 발주 경쟁이 이어진다.","eImp":"Mid-sized carriers expanding with large LNG/ammonia-ready PCTCs underscore the newbuild race for next-generation green car carriers.","url":"https://www.marinelink.com/news/sallaum-lines-orders-lng-dualfuel-pctc-541616"},{"code":"PCTC","title":"Hyundai Glovis wins series of China battery and vehicle shipping contracts","titleKR":"현대글로비스(Hyundai Glovis), 중국 배터리·완성차 해상운송 계약 잇단 수주","src":"Seoul Economic Daily","date":"2026-07-27","kSum":"현대글로비스(Hyundai Glovis)가 중국 남부 생산 EV 배터리를 헝가리·스페인·이탈리아 완성차 공장으로 운송하는 글로벌 계약을 중국 대형 배터리사와 체결했다. 반조립 부품·프레스 설비 운송과 완성차 검사·포장 계약도 확보했다.","eSum":"Hyundai Glovis signed a global ocean shipping contract with a leading Chinese battery maker to move EV batteries from south China to European plants, plus deals for knock-down parts, press equipment and vehicle inspection/packing.","kImp":"중국발 배터리·완성차 물동량이 PCTC·자동차물류 수요를 견인하며 한국 선사의 비계열 성장 흐름을 보여준다.","eImp":"Chinese battery and vehicle volumes drive PCTC and auto-logistics demand, with Korean carriers growing on non-affiliate cargo.","url":"https://en.sedaily.com/finance/2026/07/27/hyundai-glovis-wins-series-of-china-battery-vehicle"},{"code":"PCTC","title":"Hyundai Glovis looks beyond Hyundai for China growth","titleKR":"현대글로비스(Hyundai Glovis), 계열 넘어 중국 시장서 성장 모색","src":"The Korea Herald","date":"2026-07-27","kSum":"현대글로비스(Hyundai Glovis)가 중국 완성차·배터리 제조사와의 잇단 물류계약으로 비계열 고객 기반을 넓히고 있다. 중국 EV 수출 붐을 활용해 유럽·중앙아시아향 배터리·부품 운송을 확대한다.","eSum":"Hyundai Glovis is broadening its non-affiliate client base through logistics deals with Chinese carmakers and battery firms, leveraging China's EV export boom to expand shipments to Europe and Central Asia.","kImp":"중국의 EV 수출 급증이 글로벌 자동차물류 판도를 재편하며 한국 물류사에 새 성장 기회를 제공한다.","eImp":"China's EV export surge is reshaping global auto logistics, opening growth avenues for Korean logistics providers.","url":"https://www.koreaherald.com/article/10821594"},{"code":"PCTC","title":"Sallaum Lines fleet investment tops $850m with nine-ship newbuild programme","titleKR":"살라움 라인즈(Sallaum Lines), 선대 투자 8.5억 달러 돌파…신조 9척 체제","src":"Breakbulk News","date":"2026-07-30","kSum":"살라움 라인즈(Sallaum Lines)의 신규 8,600 CEU PCTC 발주로 누적 선대 투자액이 8억5천만 달러를 넘어섰다. 확정 신조는 9척으로, 4척 인도 완료, 2026년 8·12월 각 1척, 나머지는 2029년 인도된다.","eSum":"Sallaum Lines' new 8,600 CEU PCTC order pushes cumulative fleet investment past $850m. Its firm programme totals nine ships—four delivered, one due August and one December 2026, the rest in 2029.","kImp":"중견 자동차운반 선사의 공격적 신조 투자는 향후 몇 년간 PCTC 선복 확대와 친환경 전환을 예고한다.","eImp":"Aggressive newbuild investment signals continued PCTC capacity growth and accelerating green transition.","url":"https://breakbulk.news/sallaum-lines-orders-8600-ceu-carrier-as-fleet-investment-tops-850-million/"},{"code":"PCTC","title":"Dry cargo roundup: Chinese yards in focus with new Swiss car carrier order","titleKR":"건화물 뉴스 정리: 중국 조선소 집중…스위스 자동차운반선 신규 발주","src":"Baird Maritime","date":"2026-07-29","kSum":"7월 29일자 건화물 신조·인도 정리 기사는 중국 조선소가 자동차운반선·벌크선 수주·인도를 주도한다고 전했다. 스위스 살라움 라인즈의 신규 PCTC 발주가 자동차운반선 부문 핵심 소식으로 다뤄졌다.","eSum":"A 29 July dry-cargo roundup highlights Chinese yards leading car-carrier and bulker orders and deliveries, featuring Sallaum Lines' new PCTC order as the key car-carrier item.","kImp":"자동차운반선 신조가 중국 조선소로 쏠리는 구조는 향후 선복 공급과 공급망 리스크에 영향을 준다.","eImp":"Concentration of car-carrier newbuilds at Chinese yards affects future supply and supply-chain risk.","url":"https://www.bairdmaritime.com/shipping/dry-cargo/dry-cargo-vessel-news-roundup-july-29-chinese-yards-focus-bulker-deliveries-to-africa-swiss-car-carrier-order-and-more"}]},{"code":"WW","kTitle":"발레니우스 빌헬름센","eTitle":"Wallenius Wilhelmsen","items":[{"code":"WW","title":"Wallenius Wilhelmsen takes delivery of first Shaper Class vessel Arctic Tern","titleKR":"발레니우스 빌헬름센(Wallenius Wilhelmsen), 첫 셰이퍼 클래스 선박 '아틱 턴(Arctic Tern)' 인도","src":"Wallenius Wilhelmsen","date":"2026-07-09","kSum":"발레니우스 빌헬름센(Wallenius Wilhelmsen)이 7월 9일 신형 셰이퍼 클래스(Shaper Class) 1번선 '아틱 턴(Arctic Tern)'을 인도받았다. 9,300 CEU급 메탄올 이중연료선으로 육상전원·공기윤활·암모니아 대응 설계를 갖췄으며, EUKOR가 아시아-유럽 항로에 투입한다.","eSum":"Wallenius Wilhelmsen took delivery of Arctic Tern, the first of its Shaper Class, on 9 July. The 9,300 CEU methanol dual-fuel vessel features shore power, air lubrication and ammonia-ready design, and will run on the Asia-Europe trade operated by EUKOR.","kImp":"셰이퍼 클래스 인도는 2027년 넷제로 서비스를 목표로 한 선대 현대화·탈탄소 전략의 핵심 이정표다.","eImp":"The delivery is a key milestone in Wallenius Wilhelmsen's fleet renewal and net-zero-from-2027 strategy.","url":"https://www.walleniuswilhelmsen.com/news/wallenius-wilhelmsen-takes-delivery-of-first-shaper-class-vessel-marking-a-new-chapter-in-sustainable-shipping"},{"code":"WW","title":"Wallenius Wilhelmsen takes delivery of large methanol-fueled car carrier","titleKR":"발레니우스 빌헬름센(Wallenius Wilhelmsen), 대형 메탄올 추진 자동차운반선 인도","src":"The Maritime Executive","date":"2026-07-09","kSum":"발레니우스 빌헬름센(Wallenius Wilhelmsen)이 6척 시리즈의 첫 메탄올 이중연료 자동차운반선 '아틱 턴(Arctic Tern)'을 인도받았다. 향후 시리즈에는 설계용량을 11,700 CEU로 키운 선박도 포함된다.","eSum":"Wallenius Wilhelmsen received Arctic Tern, the first of six methanol dual-fuel car carriers. The wider series includes vessels upsized to a design capacity of 11,700 CEU.","kImp":"메탄올 추진 대형 PCTC 인도는 자동차운반 부문 전반의 대체연료 전환 가속을 상징한다.","eImp":"Delivery of a large methanol-fueled PCTC symbolizes accelerating alternative-fuel transition across the car-carrier segment.","url":"https://maritime-executive.com/article/wallenius-wilhelmsen-takes-delivery-of-large-methanol-fueled-car-carrier"},{"code":"WW","title":"Arctic Tern joins the Wallenius Wilhelmsen fleet","titleKR":"'아틱 턴(Arctic Tern)', 발레니우스 빌헬름센(Wallenius Wilhelmsen) 선대에 합류","src":"Heavy Lift & PFI","date":"2026-07-09","kSum":"228m 신조선 '아틱 턴(Arctic Tern)'이 발레니우스 빌헬름센(Wallenius Wilhelmsen) 선대에 합류했다. 자동차 9,350대를 실을 수 있으며 현대차그룹과 공동 소유한 EUKOR를 통해 운항된다.","eSum":"The 228-metre newbuilding Arctic Tern joined the Wallenius Wilhelmsen fleet. It carries 9,350 cars and will be deployed via EUKOR, jointly owned with Hyundai Motor Group.","kImp":"고중량·프로젝트 화물까지 아우르는 선복 확충으로 아시아-유럽 수송 역량이 강화된다.","eImp":"Added capacity spanning high-and-heavy cargo strengthens Wallenius Wilhelmsen's Asia-Europe capability.","url":"https://www.heavyliftpfi.com/news/2026/07/09/arctic-tern-joins-the-wallenius-wilhelmsen-fleet/"},{"code":"WW","title":"EUKOR Car Carriers welcomes Arctic Tern, strengthening capacity","titleKR":"EUKOR 자동차운반, '아틱 턴(Arctic Tern)' 맞이하며 고객 수송역량 강화","src":"EUKOR","date":"2026-07-16","kSum":"현대차그룹과 발레니우스 빌헬름센(Wallenius Wilhelmsen)이 공동 소유한 EUKOR가 신조 '아틱 턴(Arctic Tern)'을 선대에 맞이했다. 메탄올 이중연료로 저배출 운항이 가능하다.","eSum":"EUKOR Car Carriers, jointly owned by Hyundai Motor Group and Wallenius Wilhelmsen, welcomed the newbuild Arctic Tern, a methanol dual-fuel ship enabling lower-emission operations.","kImp":"운항사 EUKOR의 저배출 선박 확충은 현대차그룹 완성차 수출의 공급망 탈탄소에 직접 기여한다.","eImp":"EUKOR's low-emission addition directly supports supply-chain decarbonization for Hyundai's vehicle exports.","url":"https://www.eukor.com/news/eukor-car-carriers-welcomes-arctic-tern-strengthening-capacity-for-customers-and-supporting-the-future-of-sustainable-shipping"},{"code":"WW","title":"EUKOR, SIPG Energy and World Fuel complete first green methanol bunkering of Arctic Tern","titleKR":"EUKOR·SIPG 에너지·월드퓨얼, 상하이서 '아틱 턴(Arctic Tern)' 첫 그린메탄올 벙커링 완료","src":"Marine Log","date":"2026-07-21","kSum":"EUKOR, SIPG 에너지, 월드퓨얼이 7월 21일 상하이항에서 신조 '아틱 턴(Arctic Tern)'에 약 2,800톤의 그린메탄올을 STS로 공급했다. ISCC-EU 인증 도시고형폐기물 유래로 탄소집약도 25 gCO2e/MJ 미만이다.","eSum":"EUKOR, SIPG Energy and World Fuel delivered about 2,800 tonnes of green methanol to Arctic Tern via ship-to-ship at Shanghai on 21 July. The ISCC-EU certified, waste-derived methanol has a carbon intensity below 25 gCO2e/MJ.","kImp":"현지 생산 그린메탄올의 첫 국제 PCTC 벙커링으로 아시아 메탄올 벙커링 인프라 성숙을 보여준다.","eImp":"The first bunkering of locally produced green methanol for an international PCTC shows maturing Asian methanol infrastructure.","url":"https://www.marinelog.com/news/first-green-methanol-bunkering-of-new-shaper-class-car-carrier-arctic-tern/"},{"code":"WW","title":"Oceanbird completes installation and successful sea trial of its first onboard prototype","titleKR":"오션버드(Oceanbird), 첫 온보드 시제품 설치·해상시험 성공","src":"Alfa Laval","date":"2026-07-17","kSum":"알파라발(Alfa Laval)과 발레니우스 라인즈의 합작사 오션버드(Oceanbird)가 첫 온보드 Wing560의 설치·해상시운전을 성공적으로 마쳤다. 윙세일 표면은 재활용 페트병 37만 개로 제작됐으며 최적 항로에서 선박당 최대 10% 절감이 기대된다.","eSum":"Oceanbird, a JV of Alfa Laval and Wallenius Lines, completed installation and a successful sea trial of its first onboard Wing560. Its surface uses 370,000 recycled bottles and it is claimed to save up to 10% per vessel on optimal routes.","kImp":"기술 파트너 관점에서 윙세일 기술 성숙도와 재활용 소재 적용을 입증한다.","eImp":"From the technology-partner view it validates the wing sail's maturity and recycled-material use.","url":"https://www.alfalaval.com/media/news/2026/oceanbird-completes-installation-and-successful-sea-trial-of-its-first-onboard-prototype/"},{"code":"WW","title":"Oceanbird sea trials of Wing560 on Wallenius car carrier","titleKR":"발레니우스(Wallenius) 자동차운반선의 오션버드(Oceanbird) Wing560 해상 시운전","src":"World Cargo News","date":"2026-07-17","kSum":"업계지는 발레니우스 빌헬름센(Wallenius Wilhelmsen)의 'Tirranna'호에서 오션버드(Oceanbird) Wing560의 해상 시운전이 진행됐다고 보도했다. 다음 예정 설치는 2027년 봄, 미공개 선박에 Wing560 2기를 장착하는 것이다.","eSum":"Trade press reported sea trials of Oceanbird's Wing560 on Wallenius Wilhelmsen's Tirranna. The next planned installation is two Wing560 units on an undisclosed vessel in spring 2027.","kImp":"단계적 확대 로드맵은 풍력보조추진을 선대 전반으로 확산할 계획임을 시사한다.","eImp":"The phased roadmap signals a plan to scale wind-assist across the fleet.","url":"https://www.worldcargonews.com/news/2026/07/oceanbird-sea-trials-of-wing560/"},{"code":"WW","title":"GIART: creating a stronger link for your supply chain in Northern Europe","titleKR":"발레니우스 빌헬름센(Wallenius Wilhelmsen), 예테보리 GIART 터미널을 북유럽 허브로 육성","src":"Wallenius Wilhelmsen","date":"2026-06-08","kSum":"발레니우스 빌헬름센(Wallenius Wilhelmsen)이 예테보리항의 GIART 터미널을 북유럽 공급망의 핵심 허브로 육성하고 있다. 2026년 2월부터 12년 계약으로 운영을 맡았으며, 개방형 허브로 발전시킨다는 구상이다.","eSum":"Wallenius Wilhelmsen is developing GIART, the Gothenburg International Auto and RoRo Terminal, into a key Northern European hub. It took over operations under a 12-year contract from February 2026, aiming for an open, multi-carrier hub.","kImp":"터미널 사업 확대는 엔드투엔드 물류 통합과 북유럽 시장 지배력 강화를 뒷받침한다.","eImp":"Expanding terminal operations supports end-to-end logistics integration and its Northern Europe position.","url":"https://www.walleniuswilhelmsen.com/news/giart-creating-a-stronger-link-for-your-supply-chain-in-northern-europe"},{"code":"WW","title":"Strengthening our network: new trade to and from northern Finland and Sweden","titleKR":"발레니우스 빌헬름센(Wallenius Wilhelmsen), 북부 핀란드·스웨덴 신규 항로 개설","src":"Wallenius Wilhelmsen","date":"2026-06-01","kSum":"발레니우스 빌헬름센(Wallenius Wilhelmsen)이 발레니우스 솔(Wallenius SOL)과 협력해 북부 핀란드·스웨덴 교역을 위한 신규 서비스를 개설했다. 이 지역은 브레머하펜을 통해 글로벌 네트워크에 연결된다.","eSum":"Wallenius Wilhelmsen launched a new service for trade to and from northern Finland and Sweden via a partnership with Wallenius SOL, integrating the region into its global network through Bremerhaven.","kImp":"틈새 지역 네트워크 확장은 화주 밀착형 물류망 강화와 신규 화물 확보로 이어진다.","eImp":"Extending the network into niche regions strengthens shipper-focused logistics and secures new cargo.","url":"https://www.walleniuswilhelmsen.com/news/strengthening-our-network-new-trade-to-and-from-northern-finland-and-sweden"},{"code":"WW","title":"Wallenius Wilhelmsen delivers stable Q1 performance in uncertain markets","titleKR":"발레니우스 빌헬름센(Wallenius Wilhelmsen), 불확실한 시장서 안정적 1분기 실적","src":"Wallenius Wilhelmsen","date":"2026-05-06","kSum":"발레니우스 빌헬름센(Wallenius Wilhelmsen)이 1분기 조정 EBITDA 3억8,900만 달러, 순이익 1억7,700만 달러를 발표했다. 매출은 12억5,300만 달러였다. 벙커·용선 비용 상승으로 연간 EBITDA 전망을 약 16억 달러로 하향했다.","eSum":"Wallenius Wilhelmsen reported Q1 adjusted EBITDA of $389m and net profit of $177m on revenue of $1,253m. Rising bunker and capacity costs led it to trim full-year 2026 EBITDA guidance to about $1.6bn.","kImp":"강한 아시아발 물동량에도 연료·용선 비용 압박이 커지며 자동차운반선 시황의 비용 리스크를 부각한다.","eImp":"Despite strong Asia volumes, rising fuel and charter costs highlight cost risks in the car-carrier market.","url":"https://www.walleniuswilhelmsen.com/news/wallenius-wilhelmsen-delivers-stable-q1-performance-in-uncertain-markets"}]},{"code":"EE","kTitle":"에너지효율·탈탄소","eTitle":"Energy Efficiency","items":[{"code":"EE","title":"BAR Technologies: shipping must stop waiting for future fuels to decarbonise","titleKR":"BAR 테크놀로지스, \"미래연료 기다리지 말고 지금 탈탄소해야\"","src":"Manifold Times","date":"2026-07-29","kSum":"BAR 테크놀로지스(BAR Technologies)는 해운이 탈탄소를 미래연료 문제로만 취급해선 안 된다고 강조했다. 존 쿠퍼 CEO는 IMO 넷제로 확정이나 미래연료 도입을 기다리는 것이 무행동의 핑계가 돼선 안 된다고 지적했다. 2026년 말까지 10척에 23기의 윈드윙스가 장착돼 하루 약 100톤 CO2를 절감할 전망이다.","eSum":"BAR Technologies said shipping must not treat decarbonization solely as a future-fuel problem. CEO John Cooper argued waiting for IMO Net-Zero certainty or future fuels must not excuse inaction. By end-2026, 10 vessels will run 23 WindWings, saving about 100t of CO2 per day combined.","kImp":"검증된 풍력보조 기술이 대체연료 인프라 없이도 즉각적 배출 감축 수단이 될 수 있음을 강조한다.","eImp":"Proven wind-assist technology can deliver immediate emissions cuts without new alternative-fuel infrastructure.","url":"https://www.manifoldtimes.com/news/bar-technologies-shipping-must-stop-waiting-for-future-bunker-fuels-to-decarbonise"},{"code":"EE","title":"Brazil launches public consultation on biofuel bunkering rules overhaul","titleKR":"브라질, 선박용 바이오연료 벙커링 규정 개편 공개협의 착수","src":"Manifold Times","date":"2026-07-27","kSum":"브라질 석유·가스·바이오연료청(ANP)이 선박연료 규격 개정을 위한 공개협의(No.15/2026)를 개시했다. B100 상시 공급 허용, 메탄올·암모니아·수소 등 대체연료 사전 실험 승인, LNG 사전 인가제 도입 등을 담았다. 협의는 7월 28일~9월 10일 진행된다.","eSum":"Brazil's ANP opened a public consultation (No.15/2026) to revise marine fuel specs, including approving up to B100 biofuel, experimental authorization for methanol/ammonia/hydrogen, and a prior-authorization regime for LNG. It runs 28 July–10 September.","kImp":"주요 바이오연료 생산국의 규제 완화는 대체연료 벙커링 상용화와 글로벌 공급망 확대를 촉진한다.","eImp":"Regulatory easing by a major biofuel producer accelerates commercial alternative-fuel bunkering.","url":"https://www.manifoldtimes.com/news/brazil-launches-public-consultation-on-biofuel-bunkering-rules-overhaul"},{"code":"EE","title":"Zhejiang's first inland methanol-powered boxship completes trial voyage","titleKR":"저장성 첫 내륙 메탄올 추진 컨테이너선, 시험운항 완료","src":"Manifold Times","date":"2026-07-27","kSum":"저장성 최초의 내륙 메탄올 추진 컨테이너선 'Ding Li Ji 001'이 시험운항을 마쳤다. 64 TEU급으로 7월 22일 출항해 징항대운하 구간에서 추진·조종·메탄올 연료공급·안전 시스템을 검증했다. 180kW 메탄올 엔진 2기와 10㎥ 탱크로 최대 1,000km 항속거리를 낸다.","eSum":"Zhejiang's first inland methanol-powered container vessel, Ding Li Ji 001, completed trials. The 64-TEU ship tested propulsion, manoeuvring, methanol fuel supply and safety on the Grand Canal, with two 180kW methanol engines and a 10 m3 tank giving up to 1,000 km range.","kImp":"내륙수운까지 메탄올 추진이 확산되며 중국의 청정연료 적용 범위가 원양을 넘어 넓어지고 있음을 보여준다.","eImp":"Methanol propulsion spreading to inland waterways shows China's clean-fuel adoption widening beyond deep-sea.","url":"https://www.manifoldtimes.com/news/china-zhejiangs-first-inland-methanol-powered-boxship-completes-trial-voyage/"},{"code":"EE","title":"New report calls for standardised approach to safe havens on ammonia-fuelled ships","titleKR":"LR, 암모니아 추진선 '세이프 헤이븐' 표준화 촉구 보고서 발표","src":"Manifold Times","date":"2026-07-31","kSum":"로이드선급(LR) 해양탈탄소허브가 암모니아 추진선의 비상 대피구역(세이프 헤이븐) 설계·평가에 대한 공통 접근을 촉구하는 보고서를 냈다. 보호·지휘통제·접근성 3대 기능과 표준화된 최악 시나리오 시험을 권고했다.","eSum":"The Lloyd's Register Maritime Decarbonisation Hub urged a common approach to designing and assessing emergency safe havens on ammonia-fuelled ships, recommending three core functions—protection, command-and-control and accessibility—and standardized worst-case testing.","kImp":"암모니아 연료의 안전성 표준화는 독성 리스크 해소와 암모니아 추진선 상용화의 관건이다.","eImp":"Standardizing ammonia-fuel safety is key to addressing toxicity risks and enabling commercial rollout.","url":"https://www.manifoldtimes.com/news/new-report-calls-for-standardised-approach-to-safe-havens-on-ammonia-fuelled-ships"},{"code":"EE","title":"Seaspan Energy hits 150 LNG bunkering milestone in 18 months","titleKR":"시스팬 에너지(Seaspan Energy), 18개월 만에 LNG 벙커링 150회 달성","src":"Manifold Times","date":"2026-07-29","kSum":"시스팬 에너지(Seaspan Energy)가 운항 개시 2년이 채 안 돼 150번째 선박 간(STS) LNG 벙커링을 완료했다. 2024년 12월 롱비치 첫 벙커링 이후 미 서부에서 3척으로 월 평균 12회를 처리하며, LNG 벙커링 물량 세계 7위에 올랐다.","eSum":"Seaspan Energy completed its 150th ship-to-ship LNG bunkering in under two years. Since its first at Long Beach in December 2024, it runs three bunker vessels on the US West Coast, averaging 12 operations a month, now seventh globally by LNG bunkering volume.","kImp":"북미 서안 LNG 벙커링 인프라의 급성장은 태평양 항로의 저배출 연료 전환을 뒷받침한다.","eImp":"Rapid West Coast LNG bunkering growth supports the shift to lower-emission fuels on Pacific trades.","url":"https://www.manifoldtimes.com/news/seaspan-energy-hits-150-lng-bunkering-milestone-in-18-months"}]},{"code":"DIG","kTitle":"디지털화","eTitle":"Digitalization","items":[{"code":"DIG","title":"Dualog launches Workspace collaboration platform for ship and shore teams","titleKR":"두알로그(Dualog), 선-육 팀을 위한 협업 플랫폼 '워크스페이스' 출시","src":"Smart Maritime Network","date":"2026-07-31","kSum":"노르웨이 두알로그(Dualog)가 선상 승무원과 육상 직원을 단일 커뮤니케이션 환경으로 연결하는 협업 플랫폼 '워크스페이스(Workspace)'를 출시했다. 메시징·파일 공유·업무 흐름을 통합해 파편화된 도구 사용을 줄이는 것이 목표다.","eSum":"Norway's Dualog launched Workspace, a collaboration platform connecting shipboard crews and shore staff in one communications environment, unifying messaging, file sharing and workflows to reduce fragmented tools.","kImp":"선-육 커뮤니케이션 통합은 업무 효율과 선원 소통을 개선하고 관리사의 디지털 운영을 단순화한다.","eImp":"Unified ship-shore communication improves efficiency and crew engagement while simplifying managers' digital operations.","url":"https://smartmaritimenetwork.com/2026/07/31/dualog-launches-collaboration-platform-for-ship-and-shore-teams/"},{"code":"DIG","title":"TwinShip consortium updates digital-twin Data Management Plan","titleKR":"트윈십(TwinShip) 컨소시엄, 디지털트윈 데이터관리계획 개정","src":"Smart Maritime Network","date":"2026-07-30","kSum":"EU 지원 트윈십(TwinShip) 컨소시엄이 선박 디지털트윈 프로젝트의 데이터셋·데이터 아키텍처·보안조치를 담은 개정 데이터관리계획(DMP)을 발표했다. 운영 데이터의 수집·구조화·보호 방식을 구체화했다.","eSum":"The EU-backed TwinShip consortium published an updated Data Management Plan detailing datasets, data architecture and security for its ship digital-twin project, specifying how operational data is collected, structured and protected.","kImp":"디지털트윈의 실효성은 데이터 표준화·거버넌스에 달려 있어, 공개 프레임워크는 업계 도입의 참고 기준이 된다.","eImp":"Digital-twin value hinges on data governance, so a published framework offers a reference for wider adoption.","url":"https://smartmaritimenetwork.com/2026/07/30/twinship-updates-digital-twin-data-management-plan/"},{"code":"DIG","title":"OCIMF publishes first TGAIN track-guidance implementation guidance","titleKR":"OCIMF, 내륙항행 트랙가이던스(TGAIN) 첫 도입 지침 발간","src":"Smart Maritime Network","date":"2026-07-30","kSum":"OCIMF가 유럽 내륙수로에서 사용이 늘고 있는 내륙항행 트랙가이던스 어시스턴트(TGAIN)의 안전한 도입·운영을 위한 첫 지침을 발간했다. TGAIN은 선박을 사전설정 항로로 자동 조타하되 선장의 판단을 대체하지 않는 항행보조장치다.","eSum":"OCIMF published its first guidance for safely implementing Track Guidance Assistant for Inland Navigation (TGAIN) systems as their use grows on Europe's inland waterways. TGAIN auto-steers along a predefined track but does not replace the master's judgement.","kImp":"부분자율항행 확산 단계에서 표준 운영관행·교육·사이버 프레임워크를 제시해 인적요소 관리 필요성을 부각한다.","eImp":"As semi-autonomous steering spreads, it sets standard practices, training and cyber expectations, highlighting human-factors management.","url":"https://smartmaritimenetwork.com/2026/07/30/ocimf-publishes-tgain-implementation-guidance/"},{"code":"DIG","title":"PETRONAS-chartered LNG fleet adopts integrated GTT Marine performance platform","titleKR":"페트로나스(PETRONAS) 용선 LNG 선대, GTT 마린 통합 성능 플랫폼 도입","src":"The Digital Ship","date":"2026-07-27","kSum":"GTT 마린(GTT Marine)이 페트로나스(PETRONAS) 용선 LNG선대에 데이터수집·성능분석·항해최적화·화물모니터링을 단일 플랫폼으로 통합한 솔루션을 공급한다. 기상·성능모델·디지털트윈을 결합한 항해최적화를 24시간 Fleet Centre가 지원한다.","eSum":"GTT Marine will equip PETRONAS-chartered LNG carriers with a suite unifying data acquisition, performance analytics, voyage optimisation and cargo monitoring on one platform, with 24/7 Fleet Centre support combining weather, performance models and digital twins.","kImp":"파편화된 개별 도구에서 벗어나 선박 데이터·항해·화물 관리를 단일 의사결정 환경으로 통합하는 흐름을 보여준다.","eImp":"It shows the shift from fragmented point tools to a single decision environment for a major charterer's fleet.","url":"https://thedigitalship.com/news/maritime-software/petronas-charters-adopt-integrated-gtt-marine-platform-to-unify-vessel-data-and-voyage-optimisation/"},{"code":"DIG","title":"42-vessel Newport Group adds OneWeb to Starlink for dual-LEO connectivity","titleKR":"뉴포트 그룹(Newport Group) 42척, 스타링크에 원웹 추가해 이중 LEO 연결 구축","src":"The Digital Ship","date":"2026-07-27","kSum":"벌크선사 뉴포트 그룹(Newport Group)이 42척 선대에 기존 스타링크(Starlink)에 원웹(OneWeb)을 추가해 이중 저궤도(LEO) 연결 전략을 강화했다. 원웹이 스타링크 커버리지가 제한적인 지역을 보완하며 나바리노 Cosmo 플랫폼으로 통합 관리된다.","eSum":"Bulk owner Newport Group added OneWeb alongside Starlink across its 42 vessels, strengthening a dual-LEO strategy for digital operations, cybersecurity and crew welfare, managed through Navarino's Cosmo platform.","kImp":"단일 위성사업자 대신 상호보완적 다중궤도망을 결합해 연결 연속성을 확보하는 추세를 보여준다.","eImp":"It illustrates owners combining complementary multi-orbit networks for connectivity continuity.","url":"https://thedigitalship.com/news/maritime-satellite-communications/42-vessel-newport-group-adds-oneweb-to-starlink-strategy-as-dual-leo-gains-ground-in-fleet-digitalisation/"}]},{"code":"TECH","kTitle":"기술·기관","eTitle":"Technical","items":[{"code":"TECH","title":"Tsuneishi Solutions delivers first in-house methanol fuel supply system for bulker","titleKR":"쓰네이시 솔루션즈, 벌커용 자체 개발 메탄올 연료공급시스템 첫 인도","src":"Manifold Times","date":"2026-07-27","kSum":"쓰네이시 솔루션즈 도쿄베이가 중·저속 디젤엔진용 메탄올 연료공급시스템(LFSS) 1호기를 인도했다. 2024년 4월 ClassNK AiP를 받았으며 캄사르막스 벌크선에 탑재되고, 일본 내 조립로 해외 공장검사 부담을 줄였다.","eSum":"Tsuneishi Solutions Tokyobay delivered the first unit of its in-house methanol Low-flashpoint Fuel Supply System for medium/low-speed diesels. It received ClassNK AiP in April 2024, will fit a Kamsarmax bulker, and is assembled in Japan, sparing owners overseas factory testing.","kImp":"메탄올 연료공급시스템의 국산화·현지 조립은 개조·신조 비용과 리드타임을 줄여 이중연료 전환을 가속한다.","eImp":"Localized fuel supply systems lower cost and lead time for methanol conversions.","url":"https://www.manifoldtimes.com/news/tsuneishi-solutions-tokyobay-delivers-first-methanol-fuel-supply-system-for-bulker/"},{"code":"TECH","title":"Conrad Shipyard and Samsung Heavy secure ABS AiP for US-built LNG bunkering ATB","titleKR":"콘래드 조선소·삼성중공업, 미국 건조 LNG 벙커링 ATB 미국선급(ABS) AiP 획득","src":"Manifold Times","date":"2026-07-28","kSum":"미국 콘래드 조선소가 삼성중공업(SHI)과 공동으로 12,000㎥급 LNG 벙커링 예인선-바지(ATB) 설계에 대해 미국선급(ABS) AiP를 받았다. 미국 내 건조를 전제로 하며 한·미 조선협력센터 개소식에서 공개됐다.","eSum":"US-based Conrad Shipyard and Samsung Heavy Industries received an ABS Approval in Principle for a 12,000-cbm LNG bunkering articulated tug-and-barge intended for US construction, unveiled at the Korea-US Shipbuilding Partnership Center opening.","kImp":"미국 내 LNG 벙커링 신조 설계 승인으로 미국발 LNG 공급망과 한·미 조선협력이 구체화된다.","eImp":"A class-approved US-built LNG bunkering design advances domestic gas-fuel infrastructure and Korea-US cooperation.","url":"https://www.manifoldtimes.com/news/conrad-shipyard-and-shi-secure-abs-aip-for-lng-bunkering-vessel-design/"},{"code":"TECH","title":"DNV: data quality and trust, not AI itself, are shipping's real hurdles","titleKR":"DNV, \"선박 AI의 관건은 기술이 아닌 데이터 품질·신뢰\"","src":"Manifold Times","date":"2026-08-01","kSum":"DNV 해사자문의 피유시 라지(Piyush Raj) 박사는 해운 AI 도입의 관건이 기술 자체가 아니라 데이터 품질·표준화, 거버넌스·사이버보안, 파일럿을 넘어선 확장이라고 밝혔다. 예지정비·성능모니터링·디지털트윈 확산 속 선원·기술팀의 비판적 활용 역량이 요구된다.","eSum":"DNV Maritime Advisory's Dr Piyush Raj said the real challenge in maritime AI is not technology but data quality and standardization, governance and cybersecurity, and scaling beyond pilots—requiring crews and technical teams to critically apply AI outputs.","kImp":"예지정비·상태감시가 표준이 되면서 데이터 신뢰성·인력 역량이 AI 정비 효과를 좌우한다.","eImp":"As predictive maintenance becomes standard, data trust and workforce skills will determine AI-based upkeep results.","url":"https://www.manifoldtimes.com/news/qa-dnvs-piyush-raj-on-building-ai-capabilities-for-maritime-professionals/"},{"code":"TECH","title":"Lloyd's Register joins industry debate on nuclear propulsion for superyachts","titleKR":"로이드선급(Lloyd's Register), 슈퍼요트 원자력 추진 미래 논의 참여","src":"Lloyd's Register","date":"2026-07-28","kSum":"로이드선급(LR)이 슈퍼요트 분야 원자력 추진의 미래를 둘러싼 업계 논의에 기여했다. 상선·초대형 요트로 확산되는 소형모듈원자로(SMR)·용융염원자로 추진 개념에 대한 선급 차원의 기술·안전 검토 흐름의 일부다.","eSum":"Lloyd's Register contributed to an industry debate on nuclear propulsion in superyachts, reflecting classification societies' growing technical and safety engagement with SMR and molten-salt reactor concepts spreading across ships and large yachts.","kImp":"선급의 적극 참여로 무배출 장거리 추진 대안에 대한 기술·안전 프레임워크 형성이 빨라지고 있다.","eImp":"Class engagement accelerates the technical and safety frameworks for zero-emission nuclear propulsion options.","url":"https://www.lr.org/en/knowledge/press-room/press-listing/press-release/2026/lloyds-register-contributes-to-industry-debate-on-the-future-of-nuclear-propulsion-in-superyachts/"}]},{"code":"HR","kTitle":"선원·인사","eTitle":"Marine HR","items":[{"code":"HR","title":"Nautical Institute launches global seafarer technology survey","titleKR":"노티컬인스티튜트, 글로벌 선원 기술 설문조사 착수","src":"Splash247","date":"2026-07-31","kSum":"노티컬인스티튜트가 자동화·AI·원격운항·디지털 로그·연결성이 해상 업무·안전·복지·의사결정을 어떻게 바꾸는지 조사하는 '#ListeningToSeafarers' 글로벌 설문을 시작했다. 로이드선급재단과 함께하는 2년 반짜리 STEER 프로젝트의 일부다.","eSum":"The Nautical Institute launched a global #ListeningToSeafarers survey on how automation, AI, remote operations and connectivity reshape work, safety, welfare and decision-making at sea, part of the 2.5-year STEER Project with Lloyd's Register Foundation.","kImp":"기술 전환 속 선원 관점을 반영한 실질 지침 마련의 토대가 된다.","eImp":"It lays groundwork for practical, human-centred guidance as technological change accelerates.","url":"https://splash247.com/nautical-institute-launches-global-seafarer-technology-survey/"},{"code":"HR","title":"Indian seafarers to benefit from Ministry's structured onboard training programme","titleKR":"인도 선원, 정부 주도 체계적 승선 실습 프로그램 혜택","src":"Marex Media","date":"2026-07-27","kSum":"인도 항만·해운·수로부가 사전교육을 마치고 의무 승선실습을 기다리는 GP 부원·해양조리 훈련생을 위한 6개월 체계적 승선 실습 프로그램을 시작했다. 인도해운공사 관리 여객선에서 7월 15일 시작됐다.","eSum":"India's shipping ministry launched a six-month Structured Onboard Training Programme for General Purpose Rating and catering trainees awaiting mandatory sea time, begun on 15 July aboard an SCI-managed passenger vessel.","kImp":"세계 최대 선원 공급국 중 하나인 인도가 실습 병목을 해소해 취업 경로를 넓히는 조치다.","eImp":"India easing the onboard-training bottleneck widens career pathways and matters for global crew supply.","url":"https://new.marexmedia.com/2026/07/27/indian-seafarers-to-benefit-from-ministrys-structured-onboard-training-programme"},{"code":"HR","title":"NEMO taskforce examines seafarer training needs for nuclear-powered merchant ships","titleKR":"원자력해사기구(NEMO), 원자력 추진 상선 대비 선원 교육 요건 검토 TF 출범","src":"Manifold Times","date":"2026-07-28","kSum":"원자력해사기구(NEMO)가 원자력 추진 상선에 대비해 STCW 협약이 어떻게 진화해야 하는지 검토하는 태스크포스를 출범했다. 노스스탠다드 마크 스미스가 이끌며 역량 격차·비상대응 교육 요건을 진단한다.","eSum":"The Nuclear Energy Maritime Organisation launched an STCW Task Force to examine how seafarer training must evolve for nuclear-powered ships. Led by NorthStandard's Mark Smith, it maps skills gaps and emergency-response training needs.","kImp":"원자력 추진이 차세대 무탄소 옵션으로 부상하는 가운데 선원 교육 표준을 선제 준비하는 첫 제도적 움직임이다.","eImp":"It is an early institutional move to prepare seafarer training standards as nuclear propulsion emerges.","url":"https://www.manifoldtimes.com/news/nemo-taskforce-examines-seafarer-training-needs-for-nuclear-powered-merchant-ships"},{"code":"HR","title":"DMW rules strengthen support for maritime agencies and partners","titleKR":"필리핀 이주노동부(DMW), 2026년 선원 채용 규정으로 매닝사 지원 강화","src":"The Manila Times","date":"2026-07-29","kSum":"합동매닝그룹(JMG)이 약 300명의 업계 지도자를 소집해 필리핀 이주노동부(DMW)의 새 해상 채용 규정과 개정 표준선원계약서를 설명하는 브리핑을 열었다. 명확한 이해가 계약 모호함을 방지하고 면허 매닝사 준수를 보장한다고 강조했다.","eSum":"The Joint Manning Group briefed nearly 300 maritime leaders on the Philippines' new 2026 DMW sea-based recruitment rules and revised Standard Employment Contract, stressing clarity to prevent contractual ambiguities and ensure compliance.","kImp":"세계 최대 선원 공급국의 채용·계약 규정 개편은 글로벌 매닝 관행과 선원 권익에 광범위한 영향을 미친다.","eImp":"The top seafarer supplier's overhaul of recruitment rules has broad implications for global manning and seafarer rights.","url":"https://www.manilatimes.net/2026/07/29/business/maritime/dmw-rules-strengthen-support-for-maritime-agencies-and-partners/2392800"},{"code":"HR","title":"DMW reiterates safety directives for Filipino seafarers as Black Sea attacks mount","titleKR":"DMW, 흑해 공격 격화 속 필리핀 선원 안전지침·승선 거부권 재확인","src":"The Manila Times","date":"2026-08-01","kSum":"필리핀 DMW는 흑해 상선 공격이 격화되자 자문 제48호로 면허 매닝사·외국 선주에게 안전 절차·보고 의무·선원 권리 준수를 재차 지시했다. 고위험·전쟁위험구역 지정과 '승선 거부권'을 재확인하고 사전 위험평가·자발적 서면 동의 없이는 배치 불가라는 8개 지침을 제시했다.","eSum":"Through Advisory No.48, the Philippines' DMW reminded manning agencies and principals to comply with safety protocols and seafarers' rights as Black Sea attacks escalate, reaffirming warlike-zone designations and the Right to Refuse Sailing with eight directives.","kImp":"분쟁수역 항해가 늘면서 선원의 승선 거부권과 위험구역 보호가 실질적 안전·인권 쟁점으로 부상했다.","eImp":"As conflict-zone transits grow, seafarers' right to refuse sailing and warzone protections are a live safety issue.","url":"https://www.manilatimes.net/2026/08/01/business/maritime/dmw-reiterates-safety-directives-reporting-rules-for-filipino-seafarers-as-black-sea-attacks-mount/2395866"},{"code":"HR","title":"1,000 Filipino seafarers stuck in Strait of Hormuz","titleKR":"필리핀 선원 약 1,000명, 호르무즈 해협서 발 묶여","src":"The Manila Times","date":"2026-07-31","kSum":"아세안선주협회연맹(FASA) 의장에 따르면 동남아 선주 운항 약 500척에 승선한 필리핀 선원 약 1,000명이 호르무즈 해협에 발이 묶여 있다. 발이 묶인 약 2,000명 중 필리핀인이 절반 이상이며, 일부 선박이 탐지 회피로 레이더를 꺼 집계가 어렵다.","eSum":"About 1,000 Filipino seafarers aboard some 500 Southeast Asian-operated vessels are stuck in the Strait of Hormuz, per FASA's chair. Filipinos make up more than half of roughly 2,000 stranded, and data is unreliable as some ships switch off radar.","kImp":"지정학적 긴장이 선원 이동·교대에 직접적 병목을 일으키며 대규모 선원의 복지·안전 위험을 키운다.","eImp":"Geopolitical tension is directly bottlenecking crew rotation, heightening welfare and safety risks.","url":"https://www.manilatimes.net/2026/07/31/news/1000-filipino-seafarers-stuck-in-strait-of-hormuz/2395294"},{"code":"HR","title":"Filipino seafarers repatriated after Black Sea attacks","titleKR":"필리핀 선원들, 흑해 공격 이후 순차 귀국","src":"The Manila Times","date":"2026-07-29","kSum":"우크라이나 흑해 항만 인근 상선을 겨냥한 공격이 이어지며 필리핀 선원들이 순차 귀국하고 있다. 약 17척의 필리핀 선원 약 236명이 영향을 받았고 3명 사망·약 15명 부상·1명 실종으로 전해졌다. DMW는 북부 흑해 배치 일시 중단을 권고했다.","eSum":"Filipino seafarers are being repatriated after drone and missile strikes on merchant vessels near Ukrainian Black Sea ports. Around 236 Filipinos aboard some 17 vessels were affected, with three killed, about 15 injured and one missing; the DMW recommended halting deployment to the Northern Black Sea.","kImp":"분쟁수역 공격에 따른 선원 사상·대규모 귀국은 선원 안전 보호와 배치 정책의 시급성을 부각한다.","eImp":"Casualties and mass repatriations from conflict-zone attacks underline the urgency of crew safety protections.","url":"https://www.manilatimes.net/2026/07/29/business/maritime/filipino-seafarers-repatriated-after-black-sea-attacks/2392804"},{"code":"HR","title":"Employers, unions and owners unite over seafarer challenges","titleKR":"고용주·노조·선주, 선원 현안 공동 대응 합의","src":"Seatrade Maritime","date":"2026-07-29","kSum":"업계 조직 간 협력이 선원 교육·복지·신연료 전환 지원 등 현안 전반으로 확대되고 있다. 다만 대형 엔진 제조사가 디지털·고기술 보조장비를 운용할 인력을 교육하지 않는 등 선원 거주지 인근의 신기술 교육 확대가 필요하다는 지적이 나왔다.","eSum":"Cooperation between industry bodies has grown across seafarer training, welfare and new-fuel transition support. But there is a call for more training close to where seafarers live, as many engine makers are not training those who will run their high-tech equipment.","kImp":"노사·선주 공동 대응은 선원 부족·복지·신기술 역량 격차 해결의 출발점이 된다.","eImp":"Joint action is a starting point for tackling crew shortages, welfare and new-technology skills gaps.","url":"https://www.seatrade-maritime.com/management-crewing/employers-unions-and-owners-unite-over-seafarer-challenges"}]},{"code":"HSEQ","kTitle":"HSEQ","eTitle":"HSEQ","items":[{"code":"HSEQ","title":"MarinePALS calls for engineering safeguards to prevent enclosed space deaths","titleKR":"마린PALS, 밀폐구역 사망사고 예방 위한 공학적 안전장치 촉구","src":"SAFETY4SEA","date":"2026-07-28","kSum":"개정된 IMO 밀폐구역 진입 권고가 절차를 강화했지만, 마린PALS(MarinePALS)는 교육·행정통제만으로는 부족하며 공학적 안전장치가 뒷받침돼야 한다고 경고했다. 반복되는 밀폐구역 질식 사망을 막기 위한 설계 단계의 대책을 강조했다.","eSum":"Revised IMO recommendations strengthen enclosed-space entry procedures, but MarinePALS warns that training and administrative controls must be backed by engineering safeguards, stressing design-stage measures to stop recurring enclosed-space asphyxiation deaths.","kImp":"밀폐구역 사망은 해운의 대표적 반복 인명사고로, 절차를 넘어 설계·공학적 방벽이 필요함을 부각한다.","eImp":"Enclosed-space deaths are a persistent fatality type, and the call highlights the need for engineered barriers beyond procedures.","url":"https://safety4sea.com/marinepals-calls-for-engineering-safeguards-to-prevent-enclosed-space-deaths/"},{"code":"HSEQ","title":"IMO III 12: Key outcomes","titleKR":"IMO 이행소위(III 12): 주요 결과","src":"SAFETY4SEA","date":"2026-07-27","kSum":"IMO 이행소위원회(III) 제12차 회의가 7월 20~24일 열려 사고조사 분석, 항만국통제 조화, 기국 성과 등 협약 이행 관련 안건을 진전시켰다. 회원국 감사·해양사고 교훈 반영이 주요 논의였다.","eSum":"The 12th session of IMO's Sub-Committee on Implementation of IMO Instruments (III 12) met 20-24 July, advancing casualty analysis, PSC harmonization and flag-state performance items on convention implementation.","kImp":"이행소위 결과는 사고 교훈의 규정 반영과 PSC·기국 감독 강화로 이어져 현장 안전관리에 직접 영향을 준다.","eImp":"III outcomes feed casualty lessons into rules and strengthen PSC and flag oversight, directly affecting onboard safety management.","url":"https://safety4sea.com/imo-iii-12-key-outcomes/"},{"code":"HSEQ","title":"Crew Welfare Week 2026: Psychological safety is vital for a future-ready crew","titleKR":"선원복지주간 2026: 심리적 안전이 미래형 선원의 핵심","src":"SAFETY4SEA","date":"2026-07-28","kSum":"선원복지주간(Crew Welfare Week) 2026 패널에서 전문가들은 안전한 선박 운항·효과적 리더십·선원 유지를 위해 '인간 역량'과 심리적 안전이 근본적이라고 강조했다. 실수를 보고할 수 있는 문화가 안전 성과로 이어진다는 점이 부각됐다.","eSum":"At a Crew Welfare Week 2026 panel, experts stressed that human skills and psychological safety are fundamental to safe operations, effective leadership and crew retention, noting that a culture where mistakes can be reported improves safety outcomes.","kImp":"심리적 안전은 근본원인 보고·학습을 촉진해 사고 예방과 선원 유지에 직접 기여한다.","eImp":"Psychological safety promotes reporting and learning, directly aiding accident prevention and retention.","url":"https://safety4sea.com/cm-crew-welfare-week-2026-psychological-safety-is-vital-for-a-future-ready-crew/"}]},{"code":"KR","kTitle":"한국해운","eTitle":"Korean Shipping","items":[{"code":"KR","title":"STX Engine to supply eco-engines for Maersk 19,000 TEU containerships","titleKR":"STX엔진, 머스크 1.9만TEU급 컨테이너선에 친환경 엔진 공급","src":"코리아쉬핑가제트","date":"2026-07-31","kSum":"STX엔진이 덴마크 선사 머스크(Maersk)의 1.9만TEU급 컨테이너선에 탑재될 친환경 엔진을 공급한다. 국내 엔진업체가 글로벌 선사의 대형 컨테이너선 프로젝트에 참여하며 친환경 추진 수요를 확보한 사례다.","eSum":"STX Engine will supply eco-friendly engines for Maersk's 19,000 TEU containerships. The deal sees a Korean engine maker win green-propulsion work on a global carrier's large boxship programme.","kImp":"국내 기자재 업체가 대형 선사의 친환경 엔진 공급망에 진입하며 K-조선 기자재 경쟁력을 보여준다.","eImp":"A Korean equipment maker entering a major carrier's green-engine supply chain showcases K-shipbuilding component competitiveness.","url":"https://www.ksg.co.kr/news/main_newsView.jsp?pNum=147734"},{"code":"KR","title":"'Semiconductors pull, ships push': Korea's H1 exports","titleKR":"'반도체가 끌고 선박이 밀고' 韓 상반기 수출","src":"코리아쉬핑가제트","date":"2026-07-31","kSum":"LNG·LPG 운반선 등 선박 수출이 반도체와 함께 한국 상반기 수출을 견인한 것으로 나타났다. 고부가 가스운반선 인도가 이어지며 조선이 수출 실적의 핵심 축으로 작용했다.","eSum":"Ship exports, led by LNG and LPG carriers, joined semiconductors in driving Korea's first-half exports, as deliveries of high-value gas carriers made shipbuilding a key pillar of export performance.","kImp":"조선업이 반도체와 함께 한국 수출을 떠받치며 고부가 선종 수주·인도의 경제적 중요성을 보여준다.","eImp":"Shipbuilding underpinning exports alongside chips shows the economic weight of high-value vessel orders and deliveries.","url":"https://www.ksg.co.kr/news/main_newsView.jsp?pNum=147695"},{"code":"KR","title":"KMI integrates shipping research functions into policy hub","titleKR":"KMI, 해운 연구기능 통합…'해운정책' 중심 재편","src":"코리아쉬핑가제트","date":"2026-07-30","kSum":"한국해양수산개발원(KMI)이 해운 분야 연구역량을 통합하고 정책 지원 기능을 강화하는 조직 재편에 나섰다. 분산된 해운 연구를 정책 중심으로 결집해 국가 해운정책 대응력을 높이려는 취지다.","eSum":"The Korea Maritime Institute (KMI) is reorganizing to integrate its shipping research capabilities and strengthen policy support, consolidating dispersed research around policy to bolster national shipping-policy responsiveness.","kImp":"국책 연구기관의 해운 연구 결집은 한국 해운정책 수립의 전문성과 일관성을 높인다.","eImp":"Consolidating the state institute's shipping research strengthens the expertise and coherence of Korea's shipping policy.","url":"https://www.ksg.co.kr/news/main_newsView.jsp?pNum=147732"},{"code":"KR","title":"Korea Shipowners' Association signs standard-ship-design MOU with BNK Financial","titleKR":"BNK금융그룹, 한국형 표준선형 개발 MOU 체결","src":"코리아쉬핑가제트","date":"2026-07-31","kSum":"한국해운협회는 7월 31일 BNK금융그룹과 한국형 표준선형 개발을 위한 업무협약(MOU)을 체결했다. 표준화된 친환경 선형 개발과 금융 지원을 연계해 중소선사의 선대 현대화를 돕는다는 구상이다.","eSum":"The Korea Shipowners' Association signed an MOU with BNK Financial Group on 31 July to develop Korean standard ship designs, linking standardized green vessel designs with financing to help smaller owners modernize fleets.","kImp":"표준선형과 금융을 연계한 협력은 중소선사의 친환경 신조 진입 장벽을 낮춘다.","eImp":"Pairing standard designs with financing lowers the barrier for smaller owners to order green newbuilds.","url":"https://www.ksg.co.kr/news/main_newsView.jsp?pNum=147740"},{"code":"KR","title":"Korea-China route: first-half rates rise double digits","titleKR":"한중항로/ 상반기 운임 두자릿수 상승","src":"코리아쉬핑가제트","date":"2026-07-28","kSum":"한중항로 물동량과 운임이 상반기 동안 강세를 보인 것으로 집계됐다. 운임이 두 자릿수 상승하며 근해 컨테이너 항로의 수익성이 개선됐다.","eSum":"Cargo volumes and freight rates on the Korea-China route were firm in the first half, with rates rising double digits and improving profitability on the intra-Asia container trade.","kImp":"근해항로 운임 강세는 국내 근해 컨테이너 선사의 실적 개선으로 이어진다.","eImp":"Firm intra-Asia rates translate into better results for Korean short-sea container carriers.","url":"https://www.ksg.co.kr/news/main_newsView.jsp?pNum=147688"},{"code":"KR","title":"Korea-Russia route: rising volumes lift rates","titleKR":"한러항로/ 물동량 증가에 운임도 동반 상승","src":"코리아쉬핑가제트","date":"2026-07-28","kSum":"한러항로는 여름 성수기를 맞아 물동량 강세가 이어졌다. 물동량 증가와 함께 운임도 동반 상승하며 항로 시황이 개선됐다.","eSum":"The Korea-Russia route saw firm volumes into the summer peak season, with rising cargo lifting freight rates and improving the trade's conditions.","kImp":"제재·물류 재편 속에서도 한러항로 수요가 유지되며 근해 선사에 기회가 되고 있다.","eImp":"Sustained Korea-Russia demand amid sanctions and reshuffled logistics offers opportunities for short-sea carriers.","url":"https://www.ksg.co.kr/news/main_newsView.jsp?pNum=147689"},{"code":"KR","title":"Korea-Japan route: 'PanStar effect' steadies off-season","titleKR":"한일항로/ '팬스타 효과' 비수기에도 안정","src":"코리아쉬핑가제트","date":"2026-07-28","kSum":"한일항로 시황이 비수기에도 안정적인 모습을 보였다. 팬스타(PanStar)의 신규 서비스 효과 등으로 선사들이 물동량을 유지하며 운임 하락을 방어했다.","eSum":"The Korea-Japan route held steady despite the off-season, as effects from PanStar's new services helped carriers keep volumes and defend rates.","kImp":"신규 서비스 투입이 비수기 수요를 뒷받침하며 한일 근해항로의 안정성을 높인다.","eImp":"New service capacity supports off-season demand and steadies the Korea-Japan short-sea trade.","url":"https://www.ksg.co.kr/news/main_newsView.jsp?pNum=147687"},{"code":"KR","title":"Incheon Port Authority moves to revitalise Korea-China ferry passenger market","titleKR":"인천항만공사(IPA), 한중카페리 여객시장 활성화 추진","src":"코리아쉬핑가제트","date":"2026-07-31","kSum":"인천항만공사(IPA)가 한·중 카페리 여객시장 활성화를 위해 카페리 선사들과 협력에 나섰다. 여객 수요 회복과 항로 경쟁력 강화를 위한 마케팅·서비스 개선을 추진한다.","eSum":"Incheon Port Authority is working with Korea-China ferry operators to revitalise the passenger ferry market, pursuing marketing and service improvements to recover passenger demand and strengthen the routes' competitiveness.","kImp":"카페리 여객 회복은 인천항의 여객·물류 복합 경쟁력과 한중 교류 활성화에 기여한다.","eImp":"Reviving ferry passengers supports Incheon's combined passenger-cargo competitiveness and Korea-China exchange.","url":"https://www.ksg.co.kr/news/main_newsView.jsp?pNum=147738"}]},{"code":"INS","kTitle":"선체보험(H&M)","eTitle":"Hull & Machinery Insurance","items":[{"code":"INS","title":"New Active Underwriter at AXIS Syndicate 1686","titleKR":"AXIS 신디케이트 1686, 신임 액티브 언더라이터 선임","src":"Insurance Marine News","date":"2026-07-31","kSum":"로이즈(Lloyd's) 시장의 AXIS 신디케이트 1686이 신임 액티브 언더라이터를 선임했다. 해상보험 인수 부문의 리더십 교체로, 선체(H&M)·해상 리스크 인수 전략에 영향을 줄 수 있다.","eSum":"AXIS Syndicate 1686 in the Lloyd's market has appointed a new Active Underwriter, a leadership change in marine underwriting that can shape its hull (H&M) and marine risk appetite.","kImp":"주요 신디케이트의 인수 책임자 교체는 선체보험 시장의 인수 기조·요율 방향에 영향을 미칠 수 있다.","eImp":"A leadership change at a major syndicate can influence hull-market underwriting appetite and rate direction.","url":"https://insurancemarinenews.com/insurance-marine-news/new-active-underwriter-at-axis-syndicate-1686/"},{"code":"INS","title":"London market widens Red Sea high-risk zone","titleKR":"런던 시장, 홍해(Red Sea) 고위험구역 확대","src":"Insurance Marine News","date":"2026-07-31","kSum":"런던 해상보험 시장이 홍해(Red Sea) 고위험(전쟁위험)구역을 확대했다. 후티 봉쇄·공격 격화에 따른 조치로, 해당 해역 통항 선박의 전쟁위험 추가보험료(AP) 부담이 커진다.","eSum":"The London marine insurance market widened its Red Sea high-risk (war-risk) zone amid intensifying Houthi blockade and attacks, raising war-risk additional premiums for ships transiting the area.","kImp":"고위험구역 확대는 선체·전쟁위험 보험료를 끌어올려 홍해 통항의 실질 운항비를 증가시킨다.","eImp":"Widening the high-risk zone lifts hull and war-risk premiums, raising the real cost of Red Sea transits.","url":"https://insurancemarinenews.com/insurance-marine-news/london-market-widens-red-sea-high-risk-zone/"},{"code":"INS","title":"Pakistan ports removed from London war-risk list","titleKR":"파키스탄(Pakistan) 항만, 런던 전쟁위험 목록서 제외","src":"Splash247","date":"2026-08-01","kSum":"런던 해상보험 시장의 합동전쟁위원회(JWC)가 이번 주 회람을 통해 파키스탄(Pakistan)을 전쟁·해적·테러 위험 목록에서 삭제했다. 이는 3월 등재 결정을 되돌린 것으로, 파키스탄 항만 기항 선박의 추가보험료 부담이 줄어들 수 있다.","eSum":"The Joint War Committee deleted Pakistan from the London market's Listed Areas for war, piracy and terrorism risk in a circular this week, reversing its March decision and potentially reducing additional insurance costs for ships calling at Pakistani ports.","kImp":"위험목록 제외는 해당 항만 기항의 전쟁위험 추가보험료를 낮춰 무역 비용을 완화한다.","eImp":"De-listing lowers war-risk additional premiums for calls at those ports, easing trade costs.","url":"https://splash247.com/pakistan-ports-removed-from-london-war-risk-list/"}]},{"code":"PNI","kTitle":"P&I 클럽","eTitle":"P&I Clubs","items":[{"code":"PNI","title":"Britannia reports 'much-improved' 2025/26 results","titleKR":"브리타니아(Britannia), 2025/26 회계연도 '대폭 개선된' 실적 발표","src":"Insurance Marine News","date":"2026-07-31","kSum":"브리타니아 그룹(Britannia Group)이 2025/26년 6,090만 달러의 흑자를 기록하며 '대폭 개선된' 실적을 발표했다. 강한 투자 수익에 힘입어 합산비율(combined ratio)도 개선됐다.","eSum":"Britannia Group reported a $60.9m profit for 2025/26, described as a much-improved result, with a better combined ratio helped by a strong investment return.","kImp":"주요 IG 소속 P&I 클럽의 재무 건전성은 향후 보험료 갱신·일반 인상률 전망에 영향을 준다.","eImp":"A leading IG P&I club's financial health signals the direction of upcoming renewal terms and general increase levels.","url":"https://insurancemarinenews.com/insurance-marine-news/britannia-reports-much-improved-2025-26-results/"}]},{"code":"VET","kTitle":"베팅·검사","eTitle":"Vetting","items":[{"code":"VET","title":"RightShip and NorthStandard move to cut duplicate ship inspections","titleKR":"라이트십(RightShip)·노스스탠다드(NorthStandard), 중복 선박검사 축소 추진","src":"Splash247","date":"2026-07-28","kSum":"베팅기관 라이트십(RightShip)과 P&I 클럽 노스스탠다드(NorthStandard)가 기존 라이트십 검사보고서를 공유·활용해 벌크·일반화물선의 중복 승선검사를 줄이는 협약을 맺었다. 신뢰할 수 있는 검사 정보를 재사용해 선원 부담과 운항 차질을 줄이는 것이 목표다.","eSum":"Vetting body RightShip and P&I club NorthStandard agreed to share and reuse existing RightShip inspection reports to reduce duplicate onboard inspections across dry bulk and general cargo, easing crew burden and operational disruption.","kImp":"베팅·검사 정보 공유는 반복되는 선상 검사 부담을 줄이고 실질 위험 분야에 검증 자원을 집중시킨다.","eImp":"Sharing vetting data cuts repeated onboard inspections and focuses assurance effort where it improves safety.","url":"https://splash247.com/rightship-and-northstandard-move-to-cut-duplicate-ship-inspections/"}]},{"code":"CLASS","kTitle":"선급","eTitle":"Classification","items":[{"code":"CLASS","title":"Korean Register grants first 3D-printing technology safety certification","titleKR":"한국선급(KR), 3D프린팅 기술 안전성 첫 인증","src":"코리아쉬핑가제트","date":"2026-07-29","kSum":"한국선급(KR)이 7월 28일 대전 소재 에이엠솔루션즈의 레이저 와이어 적층(3D프린팅) 기술에 대해 첫 안전성 인증을 부여했다. 선박·기자재 부품의 적층제조 적용을 위한 선급 차원의 검증 기반을 마련한 사례다.","eSum":"Korean Register (KR) granted its first safety certification for laser wire additive (3D-printing) technology to AM Solutions of Daejeon on 28 July, establishing a class basis for applying additive manufacturing to ship and equipment components.","kImp":"선급의 3D프린팅 인증은 선상 부품 적층제조·현장 제작 도입을 앞당겨 공급망·정비 효율을 높인다.","eImp":"Class certification of 3D printing advances additive manufacturing of ship parts, improving supply-chain and maintenance efficiency.","url":"https://www.ksg.co.kr/news/main_newsView.jsp?pNum=147723"},{"code":"CLASS","title":"Stella Maris UK welcomes IACS Sec-Gen Robert Ashdown as new Chair","titleKR":"스텔라 마리스 UK, IACS 사무총장 로버트 애쉬다운을 신임 의장으로 선임","src":"SAFETY4SEA","date":"2026-07-29","kSum":"국제선급연합회(IACS) 사무총장 로버트 애쉬다운(Robert Ashdown)이 선원복지단체 스텔라 마리스(Stella Maris) 영국지부의 신임 의장으로 선임됐다. 선급 리더십이 선원복지 거버넌스에 참여하는 사례로, 안전과 인적요소의 연계를 보여준다.","eSum":"IACS Secretary-General Robert Ashdown has been appointed new Chair of Stella Maris UK, the seafarer welfare charity. A class-industry leader taking a welfare-governance role links technical safety with the human element.","kImp":"선급 지도부의 복지 거버넌스 참여는 기술 안전과 선원복지의 통합적 접근을 상징한다.","eImp":"A class leader in welfare governance symbolizes an integrated approach to technical safety and seafarer welfare.","url":"https://safety4sea.com/stella-maris-uk-welcomes-iacs-sec-gen-robert-ashdown-as-new-chair/"}]},{"code":"COMM","kTitle":"상업·시황","eTitle":"Commercial & Markets","items":[{"code":"COMM","title":"China vehicle exports outgrow PCTC fleet, keeping car-carrier market tight","titleKR":"중국 완성차 수출이 PCTC 선복 능가…자동차운반선 시황 강세 지속","src":"APLF","date":"2026-07-29","kSum":"2026년 상반기 중국 완성차 수출이 500만 대를 넘어 전년比 약 65% 급증한 반면, 순수 자동차·트럭 운반선(PCTC) 선복 증가율은 약 7.6%에 그쳤다. 수급 불균형으로 약 200만 대가 컨테이너 등 대체 수단으로 이동할 전망이다.","eSum":"China's H1 2026 vehicle exports topped 5 million units, up about 65% year-on-year, while PCTC fleet supply grew only about 7.6%. The imbalance is expected to push an estimated 2 million vehicles onto alternative modes such as containers.","kImp":"수요가 선복 증가를 앞지르며 PCTC 용선료·선가 강세가 이어져 자동차운반선 시장의 구조적 강세를 뒷받침한다.","eImp":"Demand outpacing supply keeps PCTC charter rates and asset values firm, supporting structural strength in the car-carrier market.","url":"https://www.aplf.com/2026/07/29/future-development-of-china-vehicle-exports/"},{"code":"COMM","title":"Record 2m cars tipped to move in containers as China outgrows car-carrier fleet","titleKR":"중국 자동차 수출이 PCTC 선복 넘어서며 사상 최대 200만 대 컨테이너 운송 전망","src":"Splash247","date":"2026-07-21","kSum":"전용 자동차운반선(PCTC) 선복 부족으로 올해 사상 최대 약 200만 대의 자동차가 컨테이너 등 비전용선으로 운송될 전망이다. 중국 자동차 수출 급증 속도가 카캐리어 선대 증가를 앞지르고 있다.","eSum":"A record two million cars are expected to move this year on vessels other than dedicated car carriers, as China's auto-export growth outpaces PCTC fleet capacity, pushing cargo into containers.","kImp":"PCTC 선복 타이트와 높은 용선료가 지속될 수 있음을 시사하며 카캐리어 시장 수급에 직접 영향을 준다.","eImp":"It signals continued tightness and firm charter rates in the car-carrier segment.","url":"https://splash247.com/record-2m-cars-tipped-to-move-in-containers-as-china-outgrows-car-carrier-fleet/"},{"code":"COMM","title":"Wagenborg exits roros with Wallenius SOL ship sale","titleKR":"바겐보르흐(Wagenborg), 로로선 매각으로 순수 RoRo 사업 철수","src":"Splash247","date":"2026-07-31","kSum":"네덜란드 선주 로열 바겐보르흐(Royal Wagenborg)가 아이스클래스 자매선 'Bothniaborg'·'Balticborg'를 발레니우스 솔(Wallenius SOL)에 매각하며 순수 로로(RoRo) 부문에서 철수한다. 스머핏 웨스트록과의 장기 운송계약도 함께 이전된다.","eSum":"Dutch owner Royal Wagenborg is exiting the pure roro sector by selling ice-class sisters Bothniaborg and Balticborg to Wallenius SOL. The deal also transfers Wagenborg's long-term contract of affreightment with Smurfit Westrock.","kImp":"로로선 자산·계약 이전은 유럽 RoRo·자동차운반 시장의 통합과 선복 재편 흐름을 보여준다.","eImp":"The roro asset and contract transfer illustrates consolidation and capacity reshuffling in Europe's RoRo/car-carrier market.","url":"https://splash247.com/wagenborg-exits-roros-with-wallenius-sol-ship-sale/"},{"code":"COMM","title":"New York-New Jersey holds first-half volumes at 4.4m teu","titleKR":"뉴욕·뉴저지항, 상반기 물동량 440만 TEU로 유지","src":"Splash247","date":"2026-08-01","kSum":"뉴욕·뉴저지항이 2026년 상반기 440만 TEU를 처리하며 미국 수입시장 불확실성 속에서도 전년 동기와 비슷한 수준을 유지했다. 6월에는 물동량이 전년比 12% 증가하며 강한 마무리를 보였다.","eSum":"The Port of New York and New Jersey handled 4.4m teu in the first half of 2026, keeping container traffic broadly level year-on-year despite US import-market uncertainty, finishing with a strong June up 12%.","kImp":"미 동안 최대 관문항의 물동량 유지는 미국 수입 컨테이너 수요의 완만한 안정세를 시사한다.","eImp":"Stable volumes at the top US East Coast gateway suggest steady, if uncertain, US import container demand.","url":"https://splash247.com/new-york-new-jersey-holds-first-half-volumes-at-4-4m-teu/"},{"code":"COMM","title":"Antwerp awards contract for major port transport overhaul","titleKR":"안트베르펜항, 대규모 항만 교통 인프라 개편 계약 발주","src":"Splash247","date":"2026-08-01","kSum":"안트베르펜-브뤼허항(Port of Antwerp-Bruges)이 화물 이동 개선을 위한 오스터빌 섬 도로·철도·교량 재개발 사업을 컨소시엄 TM Crusoë에 발주했다. 유럽 최대 화물항 중 하나의 물류 연결성을 높이는 대형 인프라 프로젝트다.","eSum":"Port of Antwerp-Bruges awarded a contract for the Oosterweel Island road, rail and bridge redevelopment to the TM Crusoë consortium, a major project to improve freight movements through one of Europe's largest cargo ports.","kImp":"핵심 항만의 육상 연결 인프라 투자는 공급망 병목 완화와 장기 경쟁력 강화에 기여한다.","eImp":"Investing in a key port's landside links eases supply-chain bottlenecks and bolsters long-term competitiveness.","url":"https://splash247.com/antwerp-awards-contract-for-major-port-transport-overhaul/"}]},{"code":"GEO","kTitle":"지정학","eTitle":"Geopolitics","items":[{"code":"GEO","title":"Iran remains chief suspect as Damietta damage picture emerges","titleKR":"이집트 다미에타(Damietta) 피해 윤곽…이란(Iran) 유력 배후로 지목","src":"Splash247","date":"2026-07-31","kSum":"이집트 다미에타(Damietta) 항 FSRU·LNG선 드론 피격의 피해 상황이 드러나는 가운데 이란(Iran)이 유력 배후로 지목되고 있다. 미국 소유 FSRU 'Energos'가 손상됐으며 지중해 에너지 인프라로 공격이 확산될 우려가 커졌다.","eSum":"As the damage picture from the drone strike on an FSRU and LNG carrier at Egypt's Damietta emerges, Iran remains the chief suspect. The US-owned FSRU Energos was damaged, raising fears of attacks spreading to Mediterranean energy infrastructure.","kImp":"에너지 인프라로의 공격 확산 우려는 동지중해 항만·선박의 보안·보험 리스크를 키운다.","eImp":"Fears of attacks spreading to energy infrastructure raise security and insurance risk for eastern Mediterranean ports and ships.","url":"https://splash247.com/iran-remains-chief-suspect-as-damietta-damage-picture-emerges/"},{"code":"GEO","title":"Splash Wrap: War-risk map widens","titleKR":"스플래시 랩: 확대되는 전쟁위험 지도","src":"Splash247","date":"2026-07-31","kSum":"이번 주 해운 주간 정리는 흑해·홍해·동지중해로 확산되는 상선 공격과 전쟁위험구역 확대를 다뤘다. 보험 시장의 위험구역 재편과 선사의 항로·안보 대응이 핵심 이슈로 부상했다.","eSum":"This week's shipping wrap covered the spread of merchant-vessel attacks across the Black Sea, Red Sea and eastern Mediterranean and the widening of war-risk zones, with insurers redrawing risk areas and owners recalibrating routing and security.","kImp":"전쟁위험 지도의 확대는 다수 해역에서 보험료·항로·안보 비용을 동시에 끌어올린다.","eImp":"A widening war-risk map raises premiums, routing and security costs simultaneously across multiple regions.","url":"https://splash247.com/splash-wrap-war-risk-map-widens/"},{"code":"GEO","title":"Russia claims attack against three cargo vessels","titleKR":"러시아, 화물선 3척 대상 공격 주장","src":"SAFETY4SEA","date":"2026-07-30","kSum":"러시아가 흑해에서 화물선 3척을 겨냥한 공격을 주장했다. 상선을 표적으로 한 공방이 분쟁 양측에서 이어지며 흑해 통항 상선의 위험이 급격히 높아지고 있다.","eSum":"Russia claimed an attack against three cargo vessels in the Black Sea, as strikes targeting merchant ships continue on both sides of the conflict, sharply raising the risk to commercial shipping transiting the region.","kImp":"상선을 겨냥한 공방 확대는 흑해 곡물·화물 수출 항로의 운항·보험 리스크를 심화한다.","eImp":"Expanding strikes on merchant ships deepen operational and insurance risk on Black Sea grain and cargo trades.","url":"https://safety4sea.com/russia-claims-attack-against-three-cargo-vessels/"},{"code":"GEO","title":"Houthis consider establishing tolls for Red Sea passage","titleKR":"후티(Houthi), 홍해(Red Sea) 통항료 도입 검토","src":"SAFETY4SEA","date":"2026-07-30","kSum":"예멘 후티(Houthi)가 홍해(Red Sea) 통항 선박에 대한 통항료 징수 방안을 검토 중인 것으로 전해졌다. 봉쇄·공격과 병행한 '통항 관리' 시도로, 성사 시 홍해 항로의 통항 비용·규범에 중대한 변화를 가져올 수 있다.","eSum":"Yemen's Houthis are reportedly considering establishing tolls for vessels passing through the Red Sea, an attempt to 'manage' transit alongside blockade and attacks that, if realized, could significantly change transit costs and norms.","kImp":"무장세력의 통항료 시도는 국제 항행 자유를 위협하며 홍해 항로 이용의 비용·정당성 논쟁을 촉발한다.","eImp":"An armed group's toll attempt threatens freedom of navigation and stokes cost and legitimacy disputes over Red Sea transits.","url":"https://safety4sea.com/houthis-consider-establishing-tolls-for-red-sea-passage/"},{"code":"GEO","title":"South Korea refiners considering imports of Venezuelan crude, association says","titleKR":"한국 정유사, 베네수엘라(Venezuela)산 원유 수입 검토","src":"Insurance Marine News","date":"2026-07-31","kSum":"한 협회에 따르면 한국 정유사들이 베네수엘라(Venezuela)산 원유 수입을 검토하고 있다. 제재·공급 재편 속 원유 조달선 다변화 움직임으로, 장거리 원유 수송과 제재 준수 리스크에 영향을 줄 수 있다.","eSum":"South Korean refiners are considering imports of Venezuelan crude, an association said, a move to diversify crude sourcing amid sanctions and supply shifts that could affect long-haul crude shipping and sanctions-compliance risk.","kImp":"원유 조달선 다변화는 톤마일·항로 구조와 함께 선사·보험의 제재 준수 부담에 영향을 준다.","eImp":"Diversifying crude sourcing affects ton-mile and routing patterns and raises sanctions-compliance considerations for owners and insurers.","url":"https://insurancemarinenews.com/insurance-marine-news/south-korea-refiners-are-considering-imports-of-venezuelan-crude-association-says/"}]},{"code":"TW","kTitle":"트레이드윈즈 헤드라인","eTitle":"TradeWinds Headlines","items":[{"code":"TW","title":"'We're fully utilised': Kirby sees almost no impact from Jones Act waiver","titleKR":"커비(Kirby), \"선대 완전가동…존스법 면제 영향 거의 없어\"","src":"TradeWinds","date":"2026-08-01","kSum":"트레이드윈즈(TradeWinds) 헤드라인: 미국 내항 운송사 커비(Kirby)가 존스법(Jones Act) 면제에도 선대가 완전 가동 중이라 영향이 거의 없다고 밝혔다.","eSum":"TradeWinds headline: US inland/coastal operator Kirby says it is fully utilised and sees almost no impact from a Jones Act waiver.","kImp":"존스법 면제 논쟁 속 미국 내항선사의 수급 여건을 보여준다.","eImp":"It sheds light on US domestic operators' supply-demand amid the Jones Act waiver debate.","url":"https://www.tradewindsnews.com/tankers/-we-re-fully-utilised-kirby-sees-almost-no-impact-from-jones-act-waiver/2-1-2023733"},{"code":"TW","title":"US-listed shipping stocks grind out overall positive week","titleKR":"미국 상장 해운주, 전반적으로 강세 마감","src":"TradeWinds","date":"2026-08-01","kSum":"트레이드윈즈(TradeWinds) 헤드라인: 미국 상장 해운주가 한 주간 전반적으로 상승 마감했다.","eSum":"TradeWinds headline: US-listed shipping stocks ground out an overall positive week.","kImp":"해운주 강세는 투자자들의 시황 개선 기대를 반영한다.","eImp":"Firm shipping equities reflect investor expectations of improving markets.","url":"https://www.tradewindsnews.com/finance/us-listed-shipping-stocks-grind-out-overall-positive-week/2-1-2023725"},{"code":"TW","title":"Analysts lift outlook for Teekay Tankers and more could follow","titleKR":"애널리스트, 티케이 탱커스(Teekay Tankers) 전망 상향…추가 상향 가능성","src":"TradeWinds","date":"2026-08-01","kSum":"트레이드윈즈(TradeWinds) 헤드라인: 애널리스트들이 티케이 탱커스(Teekay Tankers)의 전망을 상향했으며 추가 상향이 이어질 수 있다.","eSum":"TradeWinds headline: analysts lifted the outlook for Teekay Tankers, with more upgrades possibly to follow.","kImp":"탱커 시황 강세가 상장 탱커선사 밸류에이션 개선으로 이어지고 있다.","eImp":"Firm tanker markets are feeding through to improving valuations for listed tanker owners.","url":"https://www.tradewindsnews.com/finance/analysts-lift-outlook-for-teekay-tankers-and-more-could-follow/2-1-2023720"}]},{"code":"HOT","kTitle":"호르무즈 해협 위기","eTitle":"Strait of Hormuz Crisis","items":[{"code":"HOT","title":"Hormuz oil shuttling trade is picking up again after lull","titleKR":"호르무즈 원유 셔틀 운송, 소강 이후 다시 활발","src":"gCaptain","date":"2026-07-31","kSum":"호르무즈 해협 밖으로 화물을 반출하는 데 핵심인 원유 셔틀 서비스가 최근 소강 국면을 지나 다시 활발해지고 있다. 수백만 배럴의 원유가 해협을 우회·반출되고 있다.","eSum":"The oil-shuttling service crucial to getting cargoes out of the Strait of Hormuz has picked up again after a recent lull, helping move millions of barrels.","kImp":"셔틀 운송 재개는 위기 속에서도 걸프 원유 흐름을 유지하려는 시장 적응을 보여준다.","eImp":"The rebound shows the market adapting to keep Gulf crude flowing despite the crisis.","url":"https://gcaptain.com/hormuz-oil-shuttling-trade-is-picking-up-again-after-lull/"},{"code":"HOT","title":"Turkey said to extend Iraq oil pipeline deal by one year","titleKR":"터키(Turkey), 이라크(Iraq) 송유관 협정 1년 연장","src":"gCaptain","date":"2026-08-01","kSum":"터키(Turkey)가 이라크(Iraq)와 만료된 송유관 협정을 1년 연장하기로 합의했다. 호르무즈 해협을 우회하는 육상 원유 수출 경로 확보 노력으로 해석된다.","eSum":"Turkey agreed with Iraq to extend an expired oil pipeline deal by one year, securing an overland crude export route that bypasses the Strait of Hormuz.","kImp":"호르무즈 봉쇄 위험이 커질수록 파이프라인 등 대체 수송로의 전략적 가치가 상승한다.","eImp":"As Hormuz blockade risk rises, overland pipelines gain strategic value, reshaping seaborne volumes.","url":"https://gcaptain.com/turkey-said-to-extend-iraq-oil-pipeline-deal-by-one-year/"},{"code":"HOT","title":"Oil spill from shadow-fleet tanker spreading off Oman, satellite images show","titleKR":"그림자 선단 탱커 기름 유출, 오만(Oman) 앞바다서 확산","src":"gCaptain","date":"2026-07-31","kSum":"제재 대상 탱커 한 척이 오만(Oman) 앞바다에서 기름을 유출하고 있으며 최근 수일간 유출이 확산된 것으로 위성 이미지에 나타났다. 걸프 인근 해역의 환경 피해 우려가 커지고 있다.","eSum":"A sanctions-hit tanker is leaking oil off Oman and the spill has spread in recent days, satellite images show, raising concern over environmental damage near the Gulf.","kImp":"그림자 선단의 노후·부실 운항이 호르무즈 인근 환경 재난 위험과 지역 부담을 키운다.","eImp":"Substandard shadow-fleet operations raise environmental disaster risk near Hormuz and regional burdens.","url":"https://gcaptain.com/oil-spill-from-shadow-fleet-tanker-spreading-off-oman-satellite-images-show/"},{"code":"HOT","title":"Qatar sends first LNG shipment through Hormuz in three weeks","titleKR":"카타르(Qatar), 3주 만에 호르무즈 통해 첫 LNG 선적","src":"gCaptain","date":"2026-07-30","kSum":"카타르(Qatar)가 자국 탱커 피격 이후 3주 만에 처음으로 호르무즈 해협을 통해 LNG를 선적·수송했다. 통항이 부분적으로 재개되고 있음을 보여주나 안전 우려는 여전하다.","eSum":"Qatar sent its first LNG shipment through the Strait of Hormuz since one of its tankers was attacked over three weeks ago, showing a partial resumption of transits though safety concerns persist.","kImp":"세계 최대 LNG 수출국의 통항 재개는 가스 공급 안정에 중요하나 취약한 안보 상황을 방증한다.","eImp":"A restart by the top LNG exporter matters for gas supply but underscores fragile Hormuz security.","url":"https://gcaptain.com/qatar-sends-first-lng-shipment-through-hormuz-in-three-weeks/"},{"code":"HOT","title":"Shipping industry urges protection for civilian seafarers as threats escalate","titleKR":"해운업계, 위협 고조 속 민간 선원 보호 촉구","src":"gCaptain","date":"2026-07-29","kSum":"세계 해운업계는 민간 선원들이 지정학적 분쟁의 교차사격에 점점 더 노출되고 있다고 경고하며 국제적 보호 대응을 촉구했다. 호르무즈·홍해 등지의 선박 공격 증가가 배경이다.","eSum":"The global shipping industry warned that civilian seafarers are increasingly caught in the crossfire of geopolitical conflicts and urged stronger international protection, amid rising attacks in the Hormuz and Red Sea areas.","kImp":"선원 안전 이슈는 선원 수급·사기·용선 프리미엄에 직접 영향을 주며 위기가 인적 리스크로 확대되고 있다.","eImp":"Crew-safety concerns affect manning, morale and charter premiums, extending the crisis into a human-risk dimension.","url":"https://gcaptain.com/shipping-industry-urges-protection-for-civilian-seafarers-as-global-maritime-threats-escalate/"}]},{"code":"SYS","kTitle":"해운 IT","eTitle":"Maritime IT","items":[{"code":"SYS","title":"Iridium and SKYWAVE partner on maritime IoT","titleKR":"이리듐(Iridium)-스카이웨이브(SKYWAVE), 해사 IoT 협력","src":"Smart Maritime Network","date":"2026-07-29","kSum":"이리듐(Iridium)과 스카이웨이브(SKYWAVE)가 해사 사물인터넷(IoT) 분야에서 협력하기로 했다. 위성 기반 IoT 연결로 선박·자산 모니터링을 확대해 해사 데이터 수집 인프라를 강화한다.","eSum":"Iridium and SKYWAVE partnered on maritime IoT, aiming to expand satellite-based IoT connectivity for vessel and asset monitoring and strengthen data-collection infrastructure.","kImp":"위성 IoT 확대는 실시간 선박·화물 모니터링과 예지정비 등 데이터 기반 서비스의 토대를 넓힌다.","eImp":"Expanding satellite IoT broadens the base for real-time monitoring and data-driven services like predictive maintenance.","url":"https://smartmaritimenetwork.com/2026/07/29/iridium-and-skywave-partner-on-iot/"}]},{"code":"SMGR","kTitle":"선박관리","eTitle":"Ship Management","items":[{"code":"SMGR","title":"Anglo-Eastern builds a 'single source of truth' with integrated data platform","titleKR":"앵글로-이스턴(Anglo-Eastern), 통합 데이터 플랫폼으로 '단일 진실원천' 구축","src":"The Digital Ship","date":"2026-07-30","kSum":"앵글로-이스턴(Anglo-Eastern)이 통합 데이터 플랫폼과 강화된 IT 거버넌스를 선박관리 모델의 중심에 두고 있다. 'My Anglo-Eastern' 포털이 JiBe·바르질라 함대운영시스템 데이터를 결합해 선주·육상·선원이 동일한 검증 데이터를 활용하도록 한다.","eSum":"Anglo-Eastern is placing an integrated data platform and stronger IT governance at the centre of its ship-management model. Its My Anglo-Eastern portal combines data from JiBe and Wärtsilä's Fleet Operating System so owners, shore teams and crews work from the same verified data.","kImp":"3자 관리사가 디지털 투명성을 경쟁력으로 내세우며 선주 대상 데이터 기반 서비스 차별화를 강화한다.","eImp":"A third-party manager positioning digital transparency as a competitive edge strengthens data-driven service differentiation.","url":"https://thedigitalship.com/news/maritime-satellite-communications/anglo-eastern-builds-a-single-source-of-truth/"},{"code":"SMGR","title":"From cadet to deck officer: an Australian seafarer's journey with Synergy Marine","titleKR":"생도에서 항해사로: 시너지 마린(Synergy Marine)과 함께한 호주 선원의 여정","src":"Synergy Marine Group","date":"2026-07-29","kSum":"시너지 마린 그룹(Synergy Marine Group)이 호주 출신 항해 생도 제이미 벨(Jamie Bell)의 경력 성장 사례를 소개했다. 아우리가·시너지를 통해 실무 경험과 글로벌 노출을 쌓으며 항해사로 성장한 과정을 담았다.","eSum":"Synergy Marine Group profiled the career development of Australian deck cadet Jamie Bell, who built hands-on experience and global exposure through Auriga and Synergy on his path to becoming a deck officer.","kImp":"선원 유치·유지가 최대 과제인 시기에 3자 관리사의 생도 육성 스토리는 인재 파이프라인과 고용주 브랜딩에 긍정적 신호다.","eImp":"With retention a top challenge, a manager's cadet-development story is a positive signal for talent pipelines and employer branding.","url":"https://www.synergymarinegroup.com/life-at-synergy/jamie-bell-deck-cadet-interview/"}]}]};